window.PAGES = window.PAGES || {};
window.PAGES["day3-theory"] = {"title": "OCI Linux, Networking & CLI/SDK \u2014 Day 3 | Interactive Learning Platform", "css": "\n/* ============================================================\n   DESIGN TOKENS\n   Palette: void black base, Oracle red signal, cool blue for\n   network/data concepts, amber for warnings/exam-tips.\n   Type: Space Grotesk-style geometric display (system stack),\n   Inter-style body (system stack), JetBrains-style mono for\n   code/terminal (system stack) \u2014 no external fonts/CDNs.\n   ============================================================ */\n:host{\n  --void:#08090b;\n  --panel:#101217;\n  --panel-2:#15171e;\n  --panel-glass: rgba(21,23,30,0.6);\n  --border: rgba(255,255,255,0.08);\n  --border-strong: rgba(255,255,255,0.16);\n  --text-1:#eef0f3;\n  --text-2:#a7acb8;\n  --text-3:#6b7180;\n  --red:#c74634;\n  --red-bright:#ff5a3c;\n  --red-dim: rgba(199,70,52,0.15);\n  --blue:#4f8cff;\n  --blue-dim: rgba(79,140,255,0.15);\n  --amber:#e8a33d;\n  --amber-dim: rgba(232,163,61,0.15);\n  --green:#3ec28f;\n  --green-dim: rgba(62,194,143,0.15);\n  --radius: 14px;\n  --radius-sm: 8px;\n  --font-display: \"Space Grotesk\",\"Avenir Next\",-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;\n  --font-body: \"Inter\",\"Avenir Next\",-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;\n  --font-mono: \"JetBrains Mono\",\"SF Mono\",Consolas,\"Liberation Mono\",monospace;\n  --shadow-lg: 0 20px 60px rgba(0,0,0,0.5);\n  --shadow-sm: 0 4px 16px rgba(0,0,0,0.35);\n}\n:host([data-theme=\"light\"]){\n  --void:#f3f2ee;\n  --panel:#ffffff;\n  --panel-2:#f7f6f2;\n  --panel-glass: rgba(255,255,255,0.7);\n  --border: rgba(10,10,10,0.08);\n  --border-strong: rgba(10,10,10,0.16);\n  --text-1:#15171c;\n  --text-2:#4b4f58;\n  --text-3:#83879160;\n  --shadow-lg: 0 20px 60px rgba(0,0,0,0.12);\n  --shadow-sm: 0 4px 16px rgba(0,0,0,0.08);\n}\n*{box-sizing:border-box; margin:0; padding:0;}\n@media (prefers-reduced-motion: reduce){\n  *{animation-duration:0.001ms !important; animation-iteration-count:1 !important; transition-duration:0.001ms !important;}\n}\n:host{scroll-behavior:smooth;}\n:host{\n  background:var(--void);\n  color:var(--text-1);\n  font-family:var(--font-body);\n  line-height:1.6;\n  -webkit-font-smoothing:antialiased;\n  overflow-x:hidden;\n  transition:background .4s ease,color .4s ease;\n}\nbody::before{\n  content:\"\";\n  position:fixed; inset:0; z-index:0; pointer-events:none;\n  background:\n    radial-gradient(ellipse 800px 500px at 15% -5%, rgba(199,70,52,0.16), transparent 60%),\n    radial-gradient(ellipse 700px 500px at 100% 20%, rgba(79,140,255,0.10), transparent 60%),\n    radial-gradient(ellipse 600px 400px at 50% 100%, rgba(199,70,52,0.08), transparent 60%);\n}\nh1,h2,h3,h4{font-family:var(--font-display); letter-spacing:-0.02em; font-weight:700; color:var(--text-1);}\ncode, .mono{font-family:var(--font-mono);}\na{color:inherit;}\n::selection{background:var(--red); color:#fff;}\n::-webkit-scrollbar{width:10px; height:10px;}\n::-webkit-scrollbar-track{background:transparent;}\n::-webkit-scrollbar-thumb{background:var(--border-strong); border-radius:10px;}\n\n/* ---------- particles / ambient bg ---------- */\n#particles{position:fixed; inset:0; z-index:0; pointer-events:none; opacity:.5;}\n\n/* ---------- progress bar ---------- */\n#progress-bar{\n  position:fixed; top:0; left:0; height:3px; width:0%;\n  background:linear-gradient(90deg,var(--red),var(--red-bright));\n  z-index:9999; box-shadow:0 0 12px var(--red-bright);\n  transition:width .1s linear;\n}\n\n/* ---------- top bar ---------- */\n#topbar{\n  position:fixed; top:0; left:0; right:0; z-index:900;\n  height:60px; display:flex; align-items:center; gap:14px;\n  padding:0 18px; margin-top:3px;\n  background:var(--panel-glass); backdrop-filter:blur(16px) saturate(140%);\n  border-bottom:1px solid var(--border);\n}\n#topbar .brand{display:flex; align-items:center; gap:10px; font-family:var(--font-display); font-weight:700; font-size:15px; white-space:nowrap;}\n#topbar .brand .dot{width:10px; height:10px; border-radius:3px; background:linear-gradient(135deg,var(--red),var(--red-bright)); box-shadow:0 0 14px var(--red-bright);}\n#sidebar-toggle{\n  background:transparent; border:1px solid var(--border); color:var(--text-2);\n  width:36px; height:36px; border-radius:var(--radius-sm); cursor:pointer; font-size:16px;\n  display:flex; align-items:center; justify-content:center; transition:.2s;\n}\n#sidebar-toggle:hover{border-color:var(--border-strong); color:var(--text-1);}\n#search-wrap{position:relative; flex:1; max-width:420px;}\n#search{\n  width:100%; background:var(--panel); border:1px solid var(--border); color:var(--text-1);\n  padding:8px 14px 8px 34px; border-radius:999px; font-size:13px; font-family:var(--font-body);\n  outline:none; transition:.2s;\n}\n#search:focus{border-color:var(--red); box-shadow:0 0 0 3px var(--red-dim);}\n#search-wrap svg{position:absolute; left:12px; top:50%; transform:translateY(-50%); width:14px; height:14px; color:var(--text-3);}\n#search-results{\n  position:absolute; top:calc(100% + 8px); left:0; right:0; background:var(--panel);\n  border:1px solid var(--border-strong); border-radius:var(--radius-sm); box-shadow:var(--shadow-lg);\n  max-height:320px; overflow-y:auto; display:none; z-index:50;\n}\n#search-results a{display:block; padding:9px 14px; font-size:13px; color:var(--text-2); border-bottom:1px solid var(--border);}\n#search-results a:hover{background:var(--panel-2); color:var(--text-1);}\n#search-results .sr-cat{font-size:10px; text-transform:uppercase; letter-spacing:.08em; color:var(--red-bright); display:block; margin-bottom:2px;}\n\n.topbar-spacer{flex:1;}\n#theme-toggle{\n  background:var(--panel); border:1px solid var(--border); color:var(--text-2);\n  width:36px; height:36px; border-radius:999px; cursor:pointer; display:flex; align-items:center; justify-content:center;\n  transition:.2s; font-size:15px;\n}\n#theme-toggle:hover{border-color:var(--red); color:var(--red-bright);}\n#score-chip{\n  display:flex; align-items:center; gap:6px; background:var(--panel); border:1px solid var(--border);\n  padding:6px 12px; border-radius:999px; font-size:12px; color:var(--text-2); white-space:nowrap;\n}\n#score-chip b{color:var(--red-bright); font-family:var(--font-display);}\n\n/* ---------- layout ---------- */\n#shell{display:flex; padding-top:63px; position:relative; z-index:1;}\n#sidebar{\n  width:270px; flex-shrink:0; height:calc(100% - 63px); position:sticky; top:63px;\n  overflow-y:auto; border-right:1px solid var(--border); padding:18px 10px 60px;\n  transition:margin-left .3s ease, opacity .3s ease;\n}\n#sidebar.collapsed{margin-left:-270px; opacity:0;}\n#sidebar .nav-group{margin-bottom:4px;}\n#sidebar .nav-head{\n  font-size:10px; text-transform:uppercase; letter-spacing:.1em; color:var(--text-3);\n  padding:14px 12px 6px; font-weight:700;\n}\n#sidebar a.nav-link{\n  display:flex; align-items:center; gap:9px; padding:8px 12px; border-radius:var(--radius-sm);\n  font-size:13.5px; color:var(--text-2); text-decoration:none; transition:.15s; border-left:2px solid transparent;\n}\n#sidebar a.nav-link:hover{background:var(--panel); color:var(--text-1);}\n#sidebar a.nav-link.active{background:var(--red-dim); color:var(--red-bright); border-left-color:var(--red-bright); font-weight:600;}\n#sidebar a.nav-link .num{font-family:var(--font-mono); font-size:10px; color:var(--text-3); width:18px;}\n\nmain{flex:1; min-width:0; padding:0 0 100px;}\n.container{max-width:980px; margin:0 auto; padding:0 32px;}\n\n/* ---------- hero ---------- */\n#hero{position:relative; padding:100px 32px 70px; overflow:hidden; text-align:left;}\n#hero .eyebrow{\n  display:inline-flex; align-items:center; gap:8px; font-size:12px; letter-spacing:.1em; text-transform:uppercase;\n  color:var(--red-bright); background:var(--red-dim); border:1px solid rgba(199,70,52,0.3);\n  padding:6px 14px; border-radius:999px; margin-bottom:22px; font-weight:600;\n}\n#hero h1{font-size:clamp(2.4rem,5vw,4.2rem); line-height:1.02; max-width:820px;}\n#hero h1 .accent{background:linear-gradient(135deg,var(--red),var(--red-bright)); -webkit-background-clip:text; background-clip:text; color:transparent;}\n#hero p.lede{max-width:620px; font-size:17px; color:var(--text-2); margin-top:22px;}\n#hero .hero-stats{display:flex; gap:34px; margin-top:40px; flex-wrap:wrap;}\n#hero .hstat b{font-family:var(--font-display); font-size:26px; display:block;}\n#hero .hstat span{font-size:12px; color:var(--text-3); text-transform:uppercase; letter-spacing:.06em;}\n#hero .cta-row{display:flex; gap:14px; margin-top:38px; flex-wrap:wrap;}\n.btn{\n  font-family:var(--font-body); font-weight:600; font-size:14px; padding:12px 22px; border-radius:999px;\n  border:1px solid var(--border-strong); cursor:pointer; transition:.2s; display:inline-flex; align-items:center; gap:8px;\n}\n.btn-primary{background:linear-gradient(135deg,var(--red),var(--red-bright)); color:#fff; border:none; box-shadow:0 8px 24px rgba(199,70,52,0.35);}\n.btn-primary:hover{transform:translateY(-2px); box-shadow:0 12px 30px rgba(199,70,52,0.45);}\n.btn-ghost{background:var(--panel); color:var(--text-1);}\n.btn-ghost:hover{border-color:var(--red); color:var(--red-bright);}\n\n/* orbiting node animation in hero */\n#hero-orbit{position:absolute; right:-60px; top:40px; width:420px; height:420px; opacity:.9; pointer-events:none;}\n@media (max-width:1100px){#hero-orbit{display:none;}}\n\n/* ---------- sections ---------- */\nsection.chapter{padding:70px 0 10px; border-top:1px solid var(--border); scroll-margin-top:80px;}\nsection.chapter:first-of-type{border-top:none;}\n.chapter-kicker{display:flex; align-items:center; gap:10px; margin-bottom:14px;}\n.chapter-kicker .idx{\n  font-family:var(--font-mono); font-size:12px; color:var(--red-bright); background:var(--red-dim);\n  padding:4px 10px; border-radius:6px; border:1px solid rgba(199,70,52,.3);\n}\n.chapter-kicker .track{font-size:11px; text-transform:uppercase; letter-spacing:.1em; color:var(--text-3);}\n.chapter h2{font-size:clamp(1.6rem,3vw,2.3rem); margin-bottom:6px;}\n.chapter .dek{color:var(--text-2); font-size:15.5px; max-width:680px; margin-bottom:30px;}\n.chapter h3{font-size:1.15rem; margin:34px 0 14px;}\n.chapter p{color:var(--text-2); font-size:15px; margin-bottom:14px; max-width:720px;}\n.chapter ul, .chapter ol{color:var(--text-2); font-size:15px; margin:0 0 16px 20px;}\n.chapter li{margin-bottom:6px;}\n.chapter strong{color:var(--text-1);}\n\n/* scroll reveal */\n.reveal{opacity:0; transform:translateY(24px); transition:opacity .7s ease, transform .7s ease;}\n.reveal.in{opacity:1; transform:translateY(0);}\n\n/* ---------- cards / panels ---------- */\n.panel{\n  background:linear-gradient(180deg,var(--panel),var(--panel-2));\n  border:1px solid var(--border); border-radius:var(--radius); padding:24px;\n  box-shadow:var(--shadow-sm); position:relative;\n}\n.panel-glow{position:relative; overflow:hidden;}\n.panel-glow::before{\n  content:\"\"; position:absolute; inset:-2px; z-index:-1; border-radius:inherit;\n  background:conic-gradient(from 180deg, var(--red), transparent 30%, var(--blue), transparent 70%, var(--red));\n  opacity:0; transition:opacity .4s;\n}\n.panel-glow:hover::before{opacity:.5;}\n.panel-glow > .panel-inner{background:var(--panel); border-radius:calc(var(--radius) - 1px); height:100%; padding:22px;}\n\n.grid{display:grid; gap:16px;}\n.grid-2{grid-template-columns:1fr 1fr;}\n.grid-3{grid-template-columns:repeat(3,1fr);}\n.grid-4{grid-template-columns:repeat(4,1fr);}\n@media (max-width:800px){.grid-2,.grid-3,.grid-4{grid-template-columns:1fr;}}\n\n.card{\n  background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm);\n  padding:18px; transition:.25s; cursor:default;\n}\n.card:hover{border-color:var(--border-strong); transform:translateY(-3px); box-shadow:var(--shadow-sm);}\n.card h4{font-size:14px; margin-bottom:8px; display:flex; align-items:center; gap:8px;}\n.card p{font-size:13.5px; margin:0; color:var(--text-2);}\n.card .tag{font-size:10px; text-transform:uppercase; letter-spacing:.06em; color:var(--red-bright); background:var(--red-dim); padding:3px 8px; border-radius:6px; margin-bottom:8px; display:inline-block;}\n\n/* ---------- callouts ---------- */\n.callout{border-radius:var(--radius-sm); padding:14px 16px; margin:16px 0; border:1px solid; font-size:14px; display:flex; gap:12px; align-items:flex-start;}\n.callout .ic{font-size:16px; flex-shrink:0; margin-top:1px;}\n.callout-tip{background:var(--green-dim); border-color:rgba(62,194,143,.35); color:var(--text-1);}\n.callout-warn{background:var(--amber-dim); border-color:rgba(232,163,61,.35); color:var(--text-1);}\n.callout-trap{background:var(--red-dim); border-color:rgba(199,70,52,.35); color:var(--text-1);}\n.callout-q{background:var(--blue-dim); border-color:rgba(79,140,255,.35); color:var(--text-1);}\n.callout b{display:block; font-size:11px; text-transform:uppercase; letter-spacing:.06em; margin-bottom:3px;}\n\n/* ---------- tables ---------- */\ntable.cmp{width:100%; border-collapse:collapse; font-size:13.5px; margin:18px 0;}\ntable.cmp th{text-align:left; color:var(--text-3); font-size:11px; text-transform:uppercase; letter-spacing:.06em; padding:10px 12px; border-bottom:1px solid var(--border-strong);}\ntable.cmp td{padding:12px; border-bottom:1px solid var(--border); color:var(--text-2);}\ntable.cmp tr:hover td{background:var(--panel);}\ntable.cmp td:first-child, table.cmp th:first-child{color:var(--text-1); font-weight:600;}\n\n/* ---------- buttons small ---------- */\n.chip-btn{\n  background:var(--panel-2); border:1px solid var(--border); color:var(--text-2); font-size:12.5px;\n  padding:7px 14px; border-radius:999px; cursor:pointer; transition:.2s; font-family:var(--font-body); font-weight:600;\n}\n.chip-btn:hover{border-color:var(--red); color:var(--red-bright);}\n.chip-btn.active{background:var(--red); color:#fff; border-color:var(--red);}\n.chip-btn:disabled{opacity:.4; cursor:not-allowed;}\n\n/* end of part1 */\n\n\n.vm-sim{display:grid; grid-template-columns:280px 1fr; gap:20px;}\n@media (max-width:800px){.vm-sim{grid-template-columns:1fr;}}\n.vm-controls{display:flex; flex-direction:column; gap:10px;}\n.vm-controls label{font-size:11px; text-transform:uppercase; letter-spacing:.06em; color:var(--text-3); margin-top:6px;}\n.vm-controls input[type=range]{width:100%; accent-color:var(--red);}\n.host-box{border:1px dashed var(--border-strong); border-radius:var(--radius-sm); padding:16px; position:relative; background:repeating-linear-gradient(135deg, rgba(255,255,255,0.015) 0 10px, transparent 10px 20px);}\n.host-meter{display:flex; justify-content:space-between; font-size:11px; color:var(--text-3); margin-bottom:6px;}\n.meter-bar{height:8px; border-radius:6px; background:var(--panel-2); overflow:hidden; margin-bottom:14px;}\n.meter-fill{height:100%; border-radius:6px; transition:width .4s ease; background:linear-gradient(90deg,var(--blue),#7db2ff);}\n.meter-fill.cpu{background:linear-gradient(90deg,var(--red),var(--red-bright));}\n.vm-list{display:flex; flex-wrap:wrap; gap:10px; min-height:60px;}\n.vm-card{width:110px; background:var(--panel); border:1px solid var(--border-strong); border-radius:10px; padding:10px; font-size:11px; animation:popIn .3s ease; position:relative;}\n.vm-card .vm-name{font-family:var(--font-mono); color:var(--blue); font-weight:700; margin-bottom:4px;}\n.vm-card .vm-x{position:absolute; top:6px; right:8px; cursor:pointer; color:var(--text-3);}\n.vm-card .vm-x:hover{color:var(--red-bright);}\n@keyframes popIn{from{opacity:0; transform:scale(.7);} to{opacity:1; transform:scale(1);}}\n.layer-stack{display:flex; flex-direction:column; gap:6px;}\n.layer-row{display:grid; grid-template-columns:130px 1fr; gap:0; border-radius:var(--radius-sm); overflow:hidden; border:1px solid var(--border);}\n.layer-label{background:var(--panel-2); display:flex; align-items:center; justify-content:center; font-family:var(--font-display); font-weight:700; font-size:13px;}\n.layer-cells{display:grid; grid-template-columns:repeat(6,1fr);}\n.layer-cell{padding:12px 6px; text-align:center; font-size:11px; border-left:1px solid var(--border); transition:.2s; cursor:default;}\n.layer-cell.you{background:var(--red-dim); color:var(--red-bright); font-weight:700;}\n.layer-cell.oracle{background:var(--blue-dim); color:var(--blue); font-weight:700;}\n.layer-cell:hover{filter:brightness(1.3);}\n.layer-legend{display:flex; gap:18px; margin-top:12px; font-size:12px; color:var(--text-2);}\n.legend-dot{width:10px; height:10px; border-radius:3px; display:inline-block; margin-right:6px; vertical-align:-1px;}\n.resp-track{position:relative; height:10px; border-radius:6px; background:linear-gradient(90deg,var(--blue) 0%,var(--blue) var(--split,50%), var(--red) var(--split,50%), var(--red) 100%); margin:30px 0 10px;}\n.resp-handle{position:absolute; top:50%; left:var(--split,50%); transform:translate(-50%,-50%); width:26px; height:26px; border-radius:50%; background:#fff; border:3px solid var(--void); cursor:grab; box-shadow:0 0 0 4px rgba(255,255,255,0.15);}\n.resp-labels{display:flex; justify-content:space-between; font-size:12px; color:var(--text-2); margin-bottom:4px;}\n.resp-layers{display:flex; flex-direction:column; gap:8px; margin-top:20px;}\n.resp-layer-row{display:flex; align-items:center; gap:12px; font-size:13px;}\n.resp-layer-row .name{width:150px; flex-shrink:0; color:var(--text-1); font-weight:600;}\n.resp-layer-row .who{font-family:var(--font-mono); font-size:11px; padding:4px 10px; border-radius:6px;}\n.who-oracle{background:var(--blue-dim); color:var(--blue);}\n.who-you{background:var(--red-dim); color:var(--red-bright);}\n.who-shared{background:var(--amber-dim); color:var(--amber);}\n.map-wrap{display:grid; grid-template-columns:1fr 260px; gap:20px;}\n@media (max-width:800px){.map-wrap{grid-template-columns:1fr;}}\n.region-dot{cursor:pointer; transition:.2s;}\n.region-dot circle{transition:.2s;}\n.region-info{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:16px; font-size:13px; min-height:180px;}\n.region-info h4{font-size:14px; color:var(--red-bright); margin-bottom:8px;}\n.region-info .placeholder{color:var(--text-3); font-style:italic;}\n.ad-buildings{display:flex; gap:16px; justify-content:center; margin:20px 0; flex-wrap:wrap;}\n.building{width:120px; text-align:center; padding:16px 10px; border-radius:var(--radius-sm); border:1px solid var(--border-strong); background:var(--panel); transition:.4s;}\n.building .roof{font-size:26px; margin-bottom:6px;}\n.building .b-name{font-family:var(--font-mono); font-size:12px; margin-bottom:4px;}\n.building .b-status{font-size:11px; padding:3px 8px; border-radius:6px; display:inline-block;}\n.b-status.ok{background:var(--green-dim); color:var(--green);}\n.b-status.down{background:var(--red-dim); color:var(--red-bright);}\n.building.failed{opacity:.4; filter:grayscale(1); transform:translateY(4px);}\n.building.shaking{animation:shake .4s;}\n@keyframes shake{0%,100%{transform:translateX(0);}25%{transform:translateX(-4px);}75%{transform:translateX(4px);}}\n.fd-rack{display:flex; gap:14px; justify-content:center; margin:20px 0; flex-wrap:wrap;}\n.rack{width:150px; border:1px solid var(--border-strong); border-radius:8px; padding:8px; background:var(--panel);}\n.rack .rack-head{font-family:var(--font-mono); font-size:11px; text-align:center; color:var(--text-3); margin-bottom:6px;}\n.rack-slot{height:20px; border-radius:4px; background:var(--panel-2); margin-bottom:4px; font-size:9px; display:flex; align-items:center; justify-content:center; color:var(--text-3); border:1px solid var(--border);}\n.rack-slot.filled{background:var(--blue-dim); color:var(--blue); border-color:rgba(79,140,255,.4); font-weight:700;}\n.rack.dead{opacity:.35;}\n.rack.dead .rack-slot.filled{background:var(--red-dim); color:var(--red-bright);}\n.calc-grid{display:grid; grid-template-columns:1fr 1fr; gap:24px;}\n@media (max-width:800px){.calc-grid{grid-template-columns:1fr;}}\n.calc-row{display:flex; align-items:center; justify-content:space-between; gap:10px; margin-bottom:14px;}\n.calc-row label{font-size:13px; color:var(--text-2);}\n.calc-row output{font-family:var(--font-mono); color:var(--red-bright); font-weight:700; font-size:13px;}\ncanvas#capexChart{width:100%; height:220px;}\n.cost-total{display:flex; justify-content:space-between; padding-top:14px; border-top:1px solid var(--border); margin-top:6px;}\n.cost-total b{font-family:var(--font-display); font-size:20px;}\n.policy-editor{background:#0c0d10; border:1px solid var(--border-strong); border-radius:var(--radius-sm); padding:16px; font-family:var(--font-mono); font-size:13.5px;}\n.policy-editor textarea{width:100%; min-height:80px; background:transparent; border:none; outline:none; color:#e8e8ea; font-family:var(--font-mono); font-size:13.5px; resize:vertical; line-height:1.7;}\n.policy-verdict{margin-top:10px; padding:10px 12px; border-radius:8px; font-size:12.5px; font-family:var(--font-body); display:none;}\n.policy-verdict.ok{display:block; background:var(--green-dim); color:var(--green);}\n.policy-verdict.bad{display:block; background:var(--red-dim); color:var(--red-bright);}\n.console-sim{border:1px solid var(--border-strong); border-radius:var(--radius); overflow:hidden; background:var(--panel);}\n.console-tb{display:flex; align-items:center; gap:10px; background:var(--panel-2); padding:10px 14px; border-bottom:1px solid var(--border);}\n.console-tb .dots span{width:10px; height:10px; border-radius:50%; display:inline-block; margin-right:5px;}\n.console-body{display:flex; min-height:320px;}\n.console-nav{width:170px; border-right:1px solid var(--border); padding:12px 8px; flex-shrink:0;}\n.console-nav div{padding:8px 10px; font-size:12.5px; border-radius:6px; cursor:pointer; color:var(--text-2); margin-bottom:2px;}\n.console-nav div.active{background:var(--red-dim); color:var(--red-bright); font-weight:700;}\n.console-main{flex:1; padding:16px;}\n.console-toolbar{display:flex; gap:8px; margin-bottom:14px;}\n.console-table{width:100%; font-size:12.5px; border-collapse:collapse;}\n.console-table th{text-align:left; font-size:10px; text-transform:uppercase; color:var(--text-3); padding:6px 8px; border-bottom:1px solid var(--border-strong);}\n.console-table td{padding:8px; border-bottom:1px solid var(--border); color:var(--text-2);}\n.console-table tr:hover td{background:var(--panel-2);}\n.status-pill{font-size:10px; padding:2px 8px; border-radius:20px;}\n.status-pill.active{background:var(--green-dim); color:var(--green);}\n.status-pill.deleted{background:var(--red-dim); color:var(--red-bright);}\n.mini-input{background:var(--panel-2); border:1px solid var(--border-strong); color:var(--text-1); border-radius:6px; padding:6px 10px; font-size:12.5px; font-family:var(--font-body);}\n.terminal{background:#0a0b0d; border:1px solid var(--border-strong); border-radius:var(--radius); overflow:hidden;}\n.terminal-tb{background:#16171c; padding:8px 14px; font-size:11px; color:var(--text-3); font-family:var(--font-mono); border-bottom:1px solid var(--border);}\n#term-out{padding:16px; font-family:var(--font-mono); font-size:12.5px; color:#c9f7d8; height:280px; overflow-y:auto; white-space:pre-wrap;}\n#term-out .cmdline{color:#7db2ff;}\n#term-out .cmdline::before{content:\"$ \"; color:var(--red-bright);}\n.term-input-row{display:flex; align-items:center; gap:8px; padding:10px 16px; border-top:1px solid var(--border); font-family:var(--font-mono); font-size:12.5px;}\n.term-input-row span{color:var(--red-bright);}\n#term-input{flex:1; background:transparent; border:none; outline:none; color:#e8e8ea; font-family:var(--font-mono); font-size:12.5px;}\n.tree{font-size:13.5px;}\n.tree ul{list-style:none; margin-left:22px; border-left:1px dashed var(--border-strong); padding-left:18px;}\n.tree li{margin:6px 0; position:relative;}\n.tree .node{display:inline-flex; align-items:center; gap:6px; padding:5px 10px; border-radius:6px; cursor:pointer; transition:.15s;}\n.tree .node:hover{background:var(--panel-2);}\n.tree .node .ic{font-size:13px;}\n.tree .node.root{color:var(--red-bright); font-weight:700;}\n.flash-wrap{display:grid; grid-template-columns:repeat(3,1fr); gap:16px;}\n@media (max-width:800px){.flash-wrap{grid-template-columns:1fr 1fr;}}\n@media (max-width:520px){.flash-wrap{grid-template-columns:1fr;}}\n.flashcard{perspective:1000px; height:130px; cursor:pointer;}\n.flashcard .fc-inner{position:relative; width:100%; height:100%; transition:transform .5s; transform-style:preserve-3d;}\n.flashcard.flipped .fc-inner{transform:rotateY(180deg);}\n.fc-face{position:absolute; inset:0; backface-visibility:hidden; border-radius:var(--radius-sm); border:1px solid var(--border-strong); padding:14px; display:flex; align-items:center; justify-content:center; text-align:center; font-size:13px;}\n.fc-front{background:var(--panel);}\n.fc-back{background:var(--red-dim); color:var(--red-bright); transform:rotateY(180deg); font-weight:600;}\n.quiz-q{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:18px 20px; margin-bottom:14px;}\n.quiz-q .qtext{font-size:14.5px; font-weight:600; margin-bottom:12px;}\n.quiz-opts{display:flex; flex-direction:column; gap:8px;}\n.quiz-opt{display:flex; align-items:center; gap:10px; padding:10px 14px; border-radius:8px; border:1px solid var(--border); cursor:pointer; font-size:13.5px; color:var(--text-2); transition:.15s;}\n.quiz-opt:hover{border-color:var(--border-strong); background:var(--panel-2);}\n.quiz-opt input{accent-color:var(--red);}\n.quiz-opt.correct{border-color:var(--green); background:var(--green-dim); color:var(--green);}\n.quiz-opt.incorrect{border-color:var(--red); background:var(--red-dim); color:var(--red-bright);}\n.quiz-explain{font-size:12.5px; color:var(--text-3); margin-top:10px; display:none; padding-top:10px; border-top:1px dashed var(--border);}\n.quiz-q.answered .quiz-explain{display:block;}\n#badge-wrap{text-align:center; padding:60px 20px;}\n.badge-circle{width:150px; height:150px; border-radius:50%; margin:0 auto 20px; position:relative; background:conic-gradient(var(--red-bright) 0deg, var(--red) var(--pct,0deg), var(--panel-2) var(--pct,0deg)); display:flex; align-items:center; justify-content:center; transition:background 1s ease;}\n.badge-circle::before{content:\"\"; position:absolute; inset:10px; border-radius:50%; background:var(--void);}\n.badge-circle span{position:relative; font-family:var(--font-display); font-size:28px; font-weight:700;}\n.center{text-align:center;}\n.mt-lg{margin-top:36px;}\n.small{font-size:12px; color:var(--text-3);}\nfooter{text-align:center; padding:50px 20px; color:var(--text-3); font-size:12.5px; border-top:1px solid var(--border); margin-top:60px;}\n.toc-jump{display:flex; gap:8px; flex-wrap:wrap; margin-top:18px;}\n\n\n/* ============================================================\n   DAY 3 \u2014 ADDITIONAL WIDGET STYLES\n   (Linux architecture layers, kernel/shell terminal, filesystem\n   tree, permission matrix + chmod sliders, process manager,\n   OSI/packet animation, subnet calculator, DNS/DHCP/NAT/TLS\n   animations, cloud shell, CLI config editor)\n   ============================================================ */\n\n/* --- linux architecture layers --- */\n.arch-stack{display:flex; flex-direction:column; gap:8px; max-width:520px; margin:0 auto;}\n.arch-layer{padding:16px; border-radius:var(--radius-sm); border:1px solid var(--border-strong); background:var(--panel); text-align:center; cursor:pointer; transition:.2s; font-weight:700; font-size:13px;}\n.arch-layer:hover, .arch-layer.active{border-color:var(--red); background:var(--red-dim); color:var(--red-bright); transform:scale(1.02);}\n.arch-detail{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:16px; margin-top:16px; font-size:13.5px; color:var(--text-2); min-height:60px;}\n\n/* --- filesystem tree --- */\n.fs-tree{font-size:13.5px;}\n.fs-node{display:inline-flex; align-items:center; gap:6px; padding:5px 10px; border-radius:6px; cursor:pointer; transition:.15s;}\n.fs-node:hover{background:var(--panel-2);}\n.fs-detail{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:14px; margin-top:12px; font-size:13px; color:var(--text-2); min-height:44px;}\n\n/* --- permission matrix / chmod --- */\n.perm-grid{display:grid; grid-template-columns:80px repeat(3,1fr); gap:1px; background:var(--border); border-radius:8px; overflow:hidden; margin:14px 0;}\n.perm-grid > div{background:var(--panel); padding:10px; text-align:center; font-size:12px;}\n.perm-grid .ph{background:var(--panel-2); font-weight:700; color:var(--text-3); text-transform:uppercase; font-size:10px; letter-spacing:.05em;}\n.perm-toggle{width:20px; height:20px; border-radius:5px; border:1px solid var(--border-strong); background:var(--panel-2); cursor:pointer; margin:0 auto; display:flex; align-items:center; justify-content:center; font-size:11px;}\n.perm-toggle.on{background:var(--red); border-color:var(--red); color:#fff;}\n.chmod-output{font-family:var(--font-mono); background:#0c0d10; border:1px solid var(--border-strong); border-radius:8px; padding:14px; margin-top:12px; color:var(--green); font-size:14px;}\n.octal-badges{display:flex; gap:10px; margin-top:10px;}\n.octal-badge{background:var(--panel-2); border:1px solid var(--border); border-radius:6px; padding:8px 14px; font-family:var(--font-mono); font-size:13px;}\n\n/* --- process manager --- */\n.proc-table{width:100%; font-size:12.5px; border-collapse:collapse;}\n.proc-table th{text-align:left; font-size:10px; text-transform:uppercase; color:var(--text-3); padding:6px 8px; border-bottom:1px solid var(--border-strong);}\n.proc-table td{padding:8px; border-bottom:1px solid var(--border); color:var(--text-2); font-family:var(--font-mono);}\n.proc-state{font-size:10px; padding:2px 8px; border-radius:20px;}\n.proc-state.running{background:var(--green-dim); color:var(--green);}\n.proc-state.stopped{background:var(--amber-dim); color:var(--amber);}\n.proc-state.zombie{background:var(--red-dim); color:var(--red-bright);}\n.service-row{display:flex; align-items:center; justify-content:space-between; padding:10px 14px; border:1px solid var(--border); border-radius:var(--radius-sm); margin-bottom:8px; font-size:13px;}\n.service-actions{display:flex; gap:6px;}\n\n/* --- OSI / TCP-IP layers --- */\n.osi-stack{display:flex; flex-direction:column-reverse; gap:5px; max-width:460px; margin:0 auto;}\n.osi-layer{padding:12px; text-align:center; border-radius:8px; border:1px solid var(--border-strong); background:var(--panel); font-size:12.5px; cursor:pointer; transition:.2s;}\n.osi-layer:hover, .osi-layer.active{border-color:var(--blue); background:var(--blue-dim); color:var(--blue);}\n.osi-tcpip-compare{display:grid; grid-template-columns:1fr 1fr; gap:10px; margin-top:20px;}\n\n/* --- packet visualizer --- */\n.packet-path{position:relative; height:90px; margin:20px 0;}\n.packet-path .node{position:absolute; top:30px; width:70px; text-align:center; font-size:11px; color:var(--text-3);}\n.packet-path .line{position:absolute; top:44px; left:0; right:0; height:2px; background:var(--border-strong);}\n.packet-dot{position:absolute; top:38px; width:14px; height:14px; border-radius:50%; background:var(--red-bright); box-shadow:0 0 12px var(--red-bright); transition:left 1s linear;}\n\n/* --- IP / CIDR calculator --- */\n.ip-octets{display:flex; gap:8px; align-items:center; font-family:var(--font-mono); font-size:20px; justify-content:center; margin:14px 0;}\n.ip-octets input{width:60px; text-align:center; background:var(--panel-2); border:1px solid var(--border-strong); color:var(--text-1); border-radius:6px; padding:8px; font-family:var(--font-mono); font-size:18px;}\n.cidr-slider{width:100%; accent-color:var(--red);}\n.ip-result-grid{display:grid; grid-template-columns:repeat(2,1fr); gap:10px; margin-top:14px;}\n.ip-result-item{background:var(--panel); border:1px solid var(--border); border-radius:8px; padding:10px 14px; font-size:12.5px;}\n.ip-result-item b{display:block; font-family:var(--font-mono); color:var(--blue); font-size:14px; margin-top:2px;}\n\n/* --- DNS/DHCP/NAT/TLS animations --- */\n.flow-steps{display:flex; align-items:center; gap:6px; overflow-x:auto; padding:10px 0; flex-wrap:wrap;}\n.flow-step{flex-shrink:0; min-width:100px; text-align:center; padding:12px 8px; border-radius:8px; background:var(--panel); border:1px solid var(--border); font-size:11.5px; transition:.3s;}\n.flow-step.lit{border-color:var(--red-bright); box-shadow:0 0 0 3px var(--red-dim); color:var(--red-bright);}\n.flow-arrow{color:var(--text-3); flex-shrink:0;}\n.nat-table{width:100%; font-size:12px; border-collapse:collapse; margin-top:10px;}\n.nat-table th{text-align:left; color:var(--text-3); font-size:10px; text-transform:uppercase; padding:6px;}\n.nat-table td{padding:6px; border-bottom:1px solid var(--border); font-family:var(--font-mono); color:var(--text-2);}\n\n/* --- cloud shell --- */\n.cloudshell{border:1px solid var(--border-strong); border-radius:var(--radius); overflow:hidden; background:#0a0b0d;}\n.cloudshell-tb{background:#16171c; padding:8px 14px; font-size:11px; color:var(--text-3); font-family:var(--font-mono); border-bottom:1px solid var(--border); display:flex; justify-content:space-between;}\n.cloudshell-tb .cs-actions span{margin-left:10px; cursor:pointer;}\n\n/* --- config file editor --- */\n.config-editor{background:#0c0d10; border:1px solid var(--border-strong); border-radius:var(--radius-sm); padding:16px; font-family:var(--font-mono); font-size:13px; color:#c9d1d9; line-height:1.8;}\n.config-editor .ck{color:#7db2ff;} .config-editor .cv{color:#8fe0b8;} .config-editor .cc{color:var(--text-3);}\n\n/* --- REST client --- */\n.rest-client{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:18px;}\n.rest-url-row{display:flex; gap:8px; margin-bottom:14px;}\n.rest-method{padding:8px 14px; border-radius:6px; font-weight:700; font-size:12px; font-family:var(--font-mono); border:1px solid var(--border-strong); background:var(--panel-2); cursor:pointer;}\n.rest-method.active-get{background:var(--green-dim); color:var(--green); border-color:var(--green);}\n.rest-method.active-post{background:var(--blue-dim); color:var(--blue); border-color:var(--blue);}\n.rest-method.active-delete{background:var(--red-dim); color:var(--red-bright); border-color:var(--red);}\n.rest-response{background:#0c0d10; border-radius:8px; padding:14px; font-family:var(--font-mono); font-size:12.5px; color:#c9f7d8; white-space:pre-wrap; margin-top:10px; min-height:60px;}\n.status-code-grid{display:grid; grid-template-columns:repeat(auto-fill,minmax(120px,1fr)); gap:10px;}\n.status-card{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:12px; text-align:center; cursor:pointer; transition:.2s;}\n.status-card:hover{border-color:var(--red);}\n.status-card .code{font-family:var(--font-display); font-size:20px; font-weight:700;}\n.status-2xx .code{color:var(--green);} .status-3xx .code{color:var(--blue);} .status-4xx .code{color:var(--amber);} .status-5xx .code{color:var(--red-bright);}\n\n/* --- comparison decision matrix --- */\n.decision-matrix{width:100%; border-collapse:collapse; font-size:13px;}\n.decision-matrix th, .decision-matrix td{padding:10px; border:1px solid var(--border); text-align:center;}\n.decision-matrix th{background:var(--panel-2); color:var(--text-1);}\n.decision-matrix td:first-child{text-align:left; font-weight:600; color:var(--text-1);}\n\n", "html": "\nHTMLEOF\nwc -l head.html<canvas id=\"particles\"></canvas>\n<div id=\"progress-bar\"></div>\n<div id=\"topbar\">\n  <button id=\"sidebar-toggle\" title=\"Toggle sidebar\">\u2630</button>\n  <div class=\"brand\"><span class=\"dot\"></span> OCI Linux, Networking &amp; CLI/SDK \u00b7 Day 3</div>\n  <div id=\"search-wrap\">\n    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"M21 21l-4.3-4.3\"/></svg>\n    <input id=\"search\" type=\"text\" placeholder=\"Search Linux, networking, CLI topics\u2026\" autocomplete=\"off\">\n    <div id=\"search-results\"></div>\n  </div>\n  <div class=\"topbar-spacer\"></div>\n  <div id=\"score-chip\">Quiz score: <b id=\"score-chip-val\">0/0</b></div>\n  <button id=\"theme-toggle\" title=\"Toggle theme\">\ud83c\udf19</button>\n</div>\n<div id=\"shell\">\n  <nav id=\"sidebar\">\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 1 \u00b7 Linux Architecture</div>\n      <a class=\"nav-link\" href=\"#sec-linuxarch\"><span class=\"num\">01</span>Architecture &amp; Kernel</a>\n      <a class=\"nav-link\" href=\"#sec-shellterm\"><span class=\"num\">02</span>Shell Terminal Lab</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 2 \u00b7 Filesystem</div>\n      <a class=\"nav-link\" href=\"#sec-filesystem\"><span class=\"num\">03</span>Filesystem Explorer</a>\n      <a class=\"nav-link\" href=\"#sec-navlab\"><span class=\"num\">04</span>Navigation Command Lab</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 3 \u00b7 Users &amp; Permissions</div>\n      <a class=\"nav-link\" href=\"#sec-users\"><span class=\"num\">05</span>Users &amp; Groups</a>\n      <a class=\"nav-link\" href=\"#sec-permissions\"><span class=\"num\">06</span>Permissions, Octal &amp; chmod</a>\n      <a class=\"nav-link\" href=\"#sec-chown\"><span class=\"num\">07</span>chown &amp; Common Mistakes</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 4 \u00b7 Processes &amp; Services</div>\n      <a class=\"nav-link\" href=\"#sec-processes\"><span class=\"num\">08</span>Processes &amp; systemd</a>\n      <a class=\"nav-link\" href=\"#sec-packages\"><span class=\"num\">09</span>Package Managers &amp; Cron</a>\n      <a class=\"nav-link\" href=\"#sec-logs\"><span class=\"num\">10</span>Logs &amp; Env Variables</a>\n      <a class=\"nav-link\" href=\"#sec-bashscript\"><span class=\"num\">11</span>Bash Scripting</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 5 \u00b7 Networking</div>\n      <a class=\"nav-link\" href=\"#sec-osi\"><span class=\"num\">12</span>OSI vs TCP/IP</a>\n      <a class=\"nav-link\" href=\"#sec-packetviz\"><span class=\"num\">13</span>Packet Visualizer</a>\n      <a class=\"nav-link\" href=\"#sec-ipv4\"><span class=\"num\">14</span>IPv4, CIDR &amp; Subnetting</a>\n      <a class=\"nav-link\" href=\"#sec-arprouting\"><span class=\"num\">15</span>ARP, Routing &amp; Switching</a>\n      <a class=\"nav-link\" href=\"#sec-dnsdhcpnat\"><span class=\"num\">16</span>DNS, DHCP &amp; NAT</a>\n      <a class=\"nav-link\" href=\"#sec-tlsssh\"><span class=\"num\">17</span>TLS/SSL, HTTPS &amp; SSH</a>\n      <a class=\"nav-link\" href=\"#sec-tcpudp\"><span class=\"num\">18</span>TCP vs UDP, Firewalls &amp; LB</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 6 \u00b7 Cloud Shell &amp; CLI</div>\n      <a class=\"nav-link\" href=\"#sec-cloudshell\"><span class=\"num\">19</span>OCI Cloud Shell</a>\n      <a class=\"nav-link\" href=\"#sec-cliauth\"><span class=\"num\">20</span>CLI Config &amp; Authentication</a>\n      <a class=\"nav-link\" href=\"#sec-clisim\"><span class=\"num\">21</span>CLI Command Simulator</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 7 \u00b7 REST &amp; SDK</div>\n      <a class=\"nav-link\" href=\"#sec-restapi\"><span class=\"num\">22</span>REST API &amp; Status Codes</a>\n      <a class=\"nav-link\" href=\"#sec-sdk\"><span class=\"num\">23</span>SDK, Signing &amp; Comparison</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 8 \u00b7 Hands-On Lab</div>\n      <a class=\"nav-link\" href=\"#sec-console3\"><span class=\"num\">24</span>Console Simulator</a>\n      <a class=\"nav-link\" href=\"#sec-terminal3\"><span class=\"num\">25</span>Linux + CLI Terminal</a>\n      <a class=\"nav-link\" href=\"#sec-troubleshoot3\"><span class=\"num\">26</span>Troubleshooting Lab</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Wrap-Up</div>\n      <a class=\"nav-link\" href=\"#sec-cheatsheet3\"><span class=\"num\">27</span>Cheat Sheets</a>\n      <a class=\"nav-link\" href=\"#sec-flashcards3\"><span class=\"num\">28</span>Flash Cards</a>\n      <a class=\"nav-link\" href=\"#sec-quiz3\"><span class=\"num\">29</span>Certification Quiz</a>\n      <a class=\"nav-link\" href=\"#sec-cert3\"><span class=\"num\">30</span>Certificate Preview</a>\n    </div>\n  </nav>\n  <main>\n    <section id=\"hero\">\n      <span class=\"eyebrow\">\u25cf Oracle Cloud Infrastructure \u2014 Linux, Networking &amp; CLI Track</span>\n      <h1>Day 3: Inside the box,<br>across the <span class=\"accent\">wire.</span></h1>\n      <p class=\"lede\">Linux internals, permissions, processes, full networking fundamentals, OCI Cloud Shell, CLI, REST APIs and SDKs \u2014 with a real-feeling terminal instead of static diagrams.</p>\n      <div class=\"hero-stats\">\n        <div class=\"hstat\"><b>30</b><span>Interactive sections</span></div>\n        <div class=\"hstat\"><b id=\"hero-quiz-count\">20</b><span>Certification MCQs</span></div>\n        <div class=\"hstat\"><b>10</b><span>Live simulators</span></div>\n        <div class=\"hstat\"><b id=\"hero-progress\">0%</b><span>Your progress</span></div>\n      </div>\n      <div class=\"cta-row\">\n        <a href=\"#sec-linuxarch\" class=\"btn btn-primary\">Start learning \u2192</a>\n        <a href=\"#sec-quiz3\" class=\"btn btn-ghost\">Jump to certification quiz</a>\n      </div>\n    </section>\n    <div class=\"container\">\n<!-- 01 LINUX ARCHITECTURE -->\n<section class=\"chapter reveal\" id=\"sec-linuxarch\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">01</span><span class=\"track\">Linux Architecture</span></div>\n  <h2>Linux Architecture &amp; Kernel</h2>\n  <p class=\"dek\">Linux began in 1991 as Linus Torvalds' hobby kernel, paired with GNU userland tools to form a complete OS. Oracle Linux, Ubuntu, RHEL, CentOS, and Debian are all distributions built around this same kernel.</p>\n  <p>Click each layer, bottom to top, to see what it does.</p>\n  <div class=\"arch-stack\" id=\"arch-stack\">\n    <div class=\"arch-layer\" data-l=\"hardware\">Hardware</div>\n    <div class=\"arch-layer\" data-l=\"kernel\">Kernel</div>\n    <div class=\"arch-layer\" data-l=\"shell\">Shell</div>\n    <div class=\"arch-layer\" data-l=\"applications\">Applications</div>\n    <div class=\"arch-layer\" data-l=\"user\">User</div>\n  </div>\n  <div class=\"arch-detail\" id=\"arch-detail\">Click a layer above to see its role, from Hardware at the bottom to the User at the top.</div>\n  <h3>What the kernel actually manages</h3>\n  <div class=\"grid grid-4\">\n    <div class=\"card\"><h4>\u23f1 Process Scheduling</h4><p>Decides which process runs on which CPU core, and for how long.</p></div>\n    <div class=\"card\"><h4>\ud83e\udde0 Memory Management</h4><p>Allocates and isolates RAM between processes via virtual memory.</p></div>\n    <div class=\"card\"><h4>\ud83d\udcc1 File System</h4><p>Presents devices and storage as a unified directory tree.</p></div>\n    <div class=\"card\"><h4>\ud83c\udf10 Networking &amp; Drivers</h4><p>Handles the network stack and talks to hardware via drivers, servicing system calls and interrupts from user space.</p></div>\n  </div>\n  <div class=\"callout callout-tip\"><div class=\"ic\">\ud83c\udf93</div><div><b>Exam Tip</b>Oracle Linux is built to be a drop-in, ABI-compatible alternative to RHEL, and offers the free Unbreakable Enterprise Kernel (UEK) \u2014 a common exam distinction point vs stock RHEL/CentOS.</div></div>\n</section>\n\n<!-- 02 SHELL TERMINAL LAB -->\n<section class=\"chapter reveal\" id=\"sec-shellterm\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">02</span><span class=\"track\">Linux Architecture</span></div>\n  <h2>Shell Terminal Lab</h2>\n  <p class=\"dek\">The shell is your interface to the kernel. Try real commands below \u2014 this is a genuine simulated filesystem, not scripted text.</p>\n  <div class=\"terminal\">\n    <div class=\"terminal-tb\">bash \u2014 oracle-linux-9 \u2014 simulator</div>\n    <div id=\"shell-out\"></div>\n    <div class=\"term-input-row\"><span id=\"shell-prompt-span\">[user@oci ~]$</span><input id=\"shell-input\" type=\"text\" autocomplete=\"off\"></div>\n  </div>\n  <p class=\"small mt-lg\">Try: <span class=\"mono\">pwd, ls, ls -la, cd docs, mkdir project, touch notes.txt, cat notes.txt, rm notes.txt, mv, cp, whoami, hostname, date, echo hello, history, clear</span></p>\n</section>\n\n<!-- 03 FILESYSTEM EXPLORER -->\n<section class=\"chapter reveal\" id=\"sec-filesystem\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">03</span><span class=\"track\">Filesystem</span></div>\n  <h2>Filesystem Hierarchy Standard</h2>\n  <p class=\"dek\">Every Linux distribution organizes itself under this same tree, rooted at <span class=\"mono\">/</span>. Click a folder for what belongs there.</p>\n  <div class=\"panel\">\n    <div class=\"fs-tree\" id=\"fs-tree\"></div>\n    <div class=\"fs-detail\" id=\"fs-detail\">Click a directory above.</div>\n  </div>\n</section>\n\n<!-- 04 NAVIGATION LAB -->\n<section class=\"chapter reveal\" id=\"sec-navlab\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">04</span><span class=\"track\">Filesystem</span></div>\n  <h2>Navigation Command Lab</h2>\n  <p class=\"dek\">Type the command that accomplishes each task. The simulator validates your answer.</p>\n  <div class=\"panel\" id=\"navlab-panel\"></div>\n</section>\n<!-- 05 USERS & GROUPS -->\n<section class=\"chapter reveal\" id=\"sec-users\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">05</span><span class=\"track\">Users &amp; Permissions</span></div>\n  <h2>Users &amp; Groups</h2>\n  <p class=\"dek\">Every process runs as a UID/GID. root (UID 0) bypasses permission checks entirely \u2014 sudo grants temporary root-equivalent access.</p>\n  <div class=\"grid grid-4\">\n    <div class=\"card\"><h4>UID / GID</h4><p>Numeric identifiers for a user and its primary group.</p></div>\n    <div class=\"card\"><h4>Home Directory</h4><p>Default working directory, usually <span class=\"mono\">/home/&lt;user&gt;</span>.</p></div>\n    <div class=\"card\"><h4>Login Shell</h4><p>The program started on login, typically <span class=\"mono\">/bin/bash</span>.</p></div>\n    <div class=\"card\"><h4>sudo</h4><p>Grants a normal user temporary elevated privileges, logged and auditable \u2014 safer than sharing the root password.</p></div>\n  </div>\n  <h3>Linux user manager</h3>\n  <div class=\"console-sim\">\n    <div class=\"console-tb\"><div class=\"dots\"><span style=\"background:#ff5f57\"></span><span style=\"background:#febc2e\"></span><span style=\"background:#28c840\"></span></div><span class=\"small mono\">/etc/passwd \u2014 user management</span></div>\n    <div class=\"console-main\" style=\"padding:16px;\">\n      <div class=\"console-toolbar\">\n        <input class=\"mini-input\" id=\"lu-new-name\" placeholder=\"new username\" style=\"flex:1;\">\n        <button class=\"chip-btn active\" id=\"lu-add-btn\">\uff0b Create User</button>\n      </div>\n      <table class=\"console-table\"><thead><tr><th>User</th><th>UID</th><th>Group</th><th>Home</th><th>Status</th><th></th></tr></thead><tbody id=\"lu-tbody\"></tbody></table>\n    </div>\n  </div>\n</section>\n\n<!-- 06 PERMISSIONS, OCTAL & CHMOD -->\n<section class=\"chapter reveal\" id=\"sec-permissions\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">06</span><span class=\"track\">Users &amp; Permissions</span></div>\n  <h2>Permissions, Octal &amp; chmod Visualizer</h2>\n  <p class=\"dek\">Toggle read/write/execute for owner, group, and others \u2014 the octal and chmod command update live.</p>\n  <div class=\"panel\">\n    <div class=\"perm-grid\" id=\"perm-grid\">\n      <div class=\"ph\"></div><div class=\"ph\">Read</div><div class=\"ph\">Write</div><div class=\"ph\">Execute</div>\n    </div>\n    <div class=\"chmod-output\" id=\"chmod-output\"># chmod 644 notes.txt</div>\n    <div class=\"octal-badges\">\n      <div class=\"octal-badge\">Owner: <span id=\"oct-owner\">6</span></div>\n      <div class=\"octal-badge\">Group: <span id=\"oct-group\">4</span></div>\n      <div class=\"octal-badge\">Others: <span id=\"oct-others\">4</span></div>\n    </div>\n    <p class=\"small mt-lg\" id=\"perm-symbolic\">Symbolic: <span class=\"mono\">-rw-r--r--</span></p>\n  </div>\n  <table class=\"cmp mt-lg\">\n    <tr><th>Octal</th><th>Symbolic</th><th>Common use</th></tr>\n    <tr><td>400</td><td>-r--------</td><td>Read-only, owner only \u2014 private keys</td></tr>\n    <tr><td>600</td><td>-rw-------</td><td>Owner read/write only \u2014 SSH private keys, secrets</td></tr>\n    <tr><td>644</td><td>-rw-r--r--</td><td>Standard file \u2014 owner edits, others read</td></tr>\n    <tr><td>700</td><td>drwx------</td><td>Private directory, owner only</td></tr>\n    <tr><td>755</td><td>drwxr-xr-x</td><td>Standard directory / executable script</td></tr>\n    <tr><td>777</td><td>drwxrwxrwx</td><td>\u26a0 Everyone can read, write, execute \u2014 almost never correct</td></tr>\n  </table>\n</section>\n\n<!-- 07 CHOWN & COMMON MISTAKES -->\n<section class=\"chapter reveal\" id=\"sec-chown\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">07</span><span class=\"track\">Users &amp; Permissions</span></div>\n  <h2>chown &amp; the chmod 777 Mistake</h2>\n  <p class=\"dek\"><span class=\"mono\">chown</span> changes ownership; <span class=\"mono\">chmod</span> changes permission bits. Both matter for who can touch a file.</p>\n  <div class=\"panel\">\n    <p class=\"mono\" style=\"color:var(--blue);\">chown newowner:newgroup file.txt</p>\n    <div class=\"grid grid-2 mt-lg\">\n      <div class=\"card\"><h4>Current owner</h4><p id=\"chown-current\">j.doe : developers</p></div>\n      <div class=\"card\"><h4>Try it</h4>\n        <input class=\"mini-input\" id=\"chown-input\" placeholder=\"e.g. admin:ops\" style=\"width:100%; margin-bottom:8px;\">\n        <button class=\"chip-btn active\" id=\"chown-apply\">Apply chown</button>\n        <p class=\"small mt-lg\" id=\"chown-result\"></p>\n      </div>\n    </div>\n  </div>\n  <h3>Why \"chmod 777\" is a common mistake</h3>\n  <div class=\"panel\">\n    <button class=\"chip-btn active\" id=\"c777-simulate\">\ud83d\udde1 Simulate what happens after chmod 777 on a web-facing script</button>\n    <p class=\"small mt-lg\" id=\"c777-result\"></p>\n  </div>\n  <div class=\"callout callout-trap\"><div class=\"ic\">\u26a0\ufe0f</div><div><b>Common Trap</b><span class=\"mono\">chmod 777</span> is frequently used as a \"quick fix\" for permission errors \u2014 it actually means every local user (and any process that gets code execution) can modify or replace the file, turning a permissions bug into a security incident.</div></div>\n</section>\n<!-- 08 PROCESSES & SYSTEMD -->\n<section class=\"chapter reveal\" id=\"sec-processes\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">08</span><span class=\"track\">Processes &amp; Services</span></div>\n  <h2>Processes &amp; systemd</h2>\n  <p class=\"dek\">Every running program is a process with a PID and a parent PPID. systemd manages long-running services.</p>\n  <div class=\"grid grid-4\">\n    <div class=\"card\"><h4>Foreground</h4><p>Occupies the terminal, blocking further input until it exits.</p></div>\n    <div class=\"card\"><h4>Background</h4><p>Runs detached from the terminal, launched with a trailing <span class=\"mono\">&amp;</span>.</p></div>\n    <div class=\"card\"><h4>Zombie</h4><p>Finished but not yet reaped by its parent \u2014 still holds a PID entry.</p></div>\n    <div class=\"card\"><h4>Daemon</h4><p>A background service with no controlling terminal, usually started at boot.</p></div>\n  </div>\n  <h3>Process manager</h3>\n  <div class=\"panel\">\n    <button class=\"chip-btn active\" id=\"proc-spawn\">\u25b6 Run new process</button>\n    <table class=\"proc-table mt-lg\"><thead><tr><th>PID</th><th>PPID</th><th>Command</th><th>State</th><th>CPU%</th><th></th></tr></thead><tbody id=\"proc-tbody\"></tbody></table>\n  </div>\n  <h3>systemd service dashboard</h3>\n  <div class=\"panel\" id=\"systemd-panel\"></div>\n</section>\n\n<!-- 09 PACKAGE MANAGERS & CRON -->\n<section class=\"chapter reveal\" id=\"sec-packages\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">09</span><span class=\"track\">Processes &amp; Services</span></div>\n  <h2>Package Managers &amp; Cron</h2>\n  <p class=\"dek\">Oracle Linux / RHEL / CentOS use <span class=\"mono\">yum</span>/<span class=\"mono\">dnf</span>; Debian/Ubuntu use <span class=\"mono\">apt</span>.</p>\n  <div class=\"panel\">\n    <div class=\"cost-filters\">\n      <button class=\"chip-btn active\" data-pm=\"dnf\">dnf (Oracle Linux/RHEL)</button>\n      <button class=\"chip-btn\" data-pm=\"apt\">apt (Ubuntu/Debian)</button>\n    </div>\n    <div style=\"display:flex; gap:8px; margin:12px 0; flex-wrap:wrap;\">\n      <input class=\"mini-input\" id=\"pkg-name\" placeholder=\"package name, e.g. nginx\" style=\"flex:1;\">\n      <button class=\"chip-btn active\" data-action=\"install\">Install</button>\n      <button class=\"chip-btn\" data-action=\"update\">Update</button>\n      <button class=\"chip-btn\" data-action=\"remove\">Remove</button>\n    </div>\n    <div class=\"terminal\" style=\"max-width:100%;\"><div id=\"pkg-out\" style=\"padding:14px; font-family:var(--font-mono); font-size:12.5px; color:#c9f7d8; min-height:60px; white-space:pre-wrap;\"></div></div>\n  </div>\n  <h3>Cron scheduler</h3>\n  <div class=\"panel\">\n    <p class=\"mono\" style=\"color:var(--blue);\">*/15 * * * * /opt/scripts/backup.sh</p>\n    <p class=\"small\">minute \u00b7 hour \u00b7 day-of-month \u00b7 month \u00b7 day-of-week</p>\n    <div style=\"display:flex; gap:8px; margin:12px 0; flex-wrap:wrap;\">\n      <input class=\"mini-input\" id=\"cron-input\" value=\"*/15 * * * *\" style=\"flex:1; font-family:var(--font-mono);\">\n      <button class=\"chip-btn active\" id=\"cron-preview\">Preview next 5 runs</button>\n    </div>\n    <div class=\"flow-steps\" id=\"cron-timeline\"></div>\n  </div>\n</section>\n\n<!-- 10 LOGS & ENV VARIABLES -->\n<section class=\"chapter reveal\" id=\"sec-logs\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">10</span><span class=\"track\">Processes &amp; Services</span></div>\n  <h2>Log Files &amp; Environment Variables</h2>\n  <p class=\"dek\">Live troubleshooting starts with logs, and every shell session carries environment context.</p>\n  <div class=\"panel\">\n    <div class=\"cost-filters\">\n      <button class=\"chip-btn active\" data-logcmd=\"journalctl -u nginx\">journalctl -u nginx</button>\n      <button class=\"chip-btn\" data-logcmd=\"tail -f /var/log/messages\">tail -f /var/log/messages</button>\n      <button class=\"chip-btn\" data-logcmd=\"grep ERROR /var/log/app.log\">grep ERROR /var/log/app.log</button>\n    </div>\n    <div class=\"terminal\" style=\"max-width:100%;\"><div id=\"log-out\" style=\"padding:14px; font-family:var(--font-mono); font-size:12px; color:#c9f7d8; min-height:100px; white-space:pre-wrap;\"></div></div>\n  </div>\n  <h3>Environment variables</h3>\n  <table class=\"cmp\">\n    <tr><th>Variable</th><th>Example value</th><th>Purpose</th></tr>\n    <tr><td class=\"mono\">PATH</td><td class=\"mono\" id=\"env-path\">/usr/local/bin:/usr/bin:/bin</td><td>Directories searched for executables</td></tr>\n    <tr><td class=\"mono\">HOME</td><td class=\"mono\">/home/opc</td><td>Current user's home directory</td></tr>\n    <tr><td class=\"mono\">USER</td><td class=\"mono\">opc</td><td>Currently logged-in username</td></tr>\n    <tr><td class=\"mono\">SHELL</td><td class=\"mono\">/bin/bash</td><td>Default login shell</td></tr>\n  </table>\n  <div style=\"display:flex; gap:8px; margin-top:10px;\">\n    <input class=\"mini-input\" id=\"env-append\" placeholder=\"/opt/myapp/bin\" style=\"flex:1;\">\n    <button class=\"chip-btn active\" id=\"env-append-btn\">Append to PATH</button>\n  </div>\n</section>\n\n<!-- 11 BASH SCRIPTING -->\n<section class=\"chapter reveal\" id=\"sec-bashscript\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">11</span><span class=\"track\">Processes &amp; Services</span></div>\n  <h2>Bash Scripting Mini Editor</h2>\n  <p class=\"dek\">Write a small script and run it in the simulator.</p>\n  <div class=\"policy-editor\"><textarea id=\"bash-editor\" spellcheck=\"false\" style=\"min-height:160px;\">#!/bin/bash\nNAME=\"OCI\"\nfor i in 1 2 3\ndo\n  echo \"Hello from $NAME, iteration $i\"\ndone\n\nif [ -f \"notes.txt\" ]; then\n  echo \"notes.txt exists\"\nelse\n  echo \"notes.txt not found\"\nfi</textarea></div>\n  <button class=\"chip-btn active\" id=\"bash-run\" style=\"margin-top:10px;\">\u25b6 Run script</button>\n  <div class=\"terminal mt-lg\" style=\"max-width:100%;\"><div id=\"bash-out\" style=\"padding:14px; font-family:var(--font-mono); font-size:12.5px; color:#c9f7d8; min-height:100px; white-space:pre-wrap;\"></div></div>\n</section>\n<!-- 12 OSI vs TCP/IP -->\n<section class=\"chapter reveal\" id=\"sec-osi\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">12</span><span class=\"track\">Networking</span></div>\n  <h2>OSI Model vs TCP/IP Model</h2>\n  <p class=\"dek\">Click each OSI layer, bottom to top, to see what happens there.</p>\n  <div class=\"osi-stack\" id=\"osi-stack\">\n    <div class=\"osi-layer\" data-o=\"physical\">1 \u00b7 Physical</div>\n    <div class=\"osi-layer\" data-o=\"datalink\">2 \u00b7 Data Link</div>\n    <div class=\"osi-layer\" data-o=\"network\">3 \u00b7 Network</div>\n    <div class=\"osi-layer\" data-o=\"transport\">4 \u00b7 Transport</div>\n    <div class=\"osi-layer\" data-o=\"session\">5 \u00b7 Session</div>\n    <div class=\"osi-layer\" data-o=\"presentation\">6 \u00b7 Presentation</div>\n    <div class=\"osi-layer\" data-o=\"application\">7 \u00b7 Application</div>\n  </div>\n  <div class=\"arch-detail\" id=\"osi-detail\">Click a layer above, starting from Physical.</div>\n  <div class=\"osi-tcpip-compare\">\n    <div class=\"card\"><h4>OSI (7 layers)</h4><p>Conceptual, granular \u2014 used for teaching and troubleshooting terminology (\"Layer 3 issue\", \"Layer 7 firewall\").</p></div>\n    <div class=\"card\"><h4>TCP/IP (4 layers)</h4><p>Application \u00b7 Transport \u00b7 Internet \u00b7 Network Access \u2014 what's actually implemented in real stacks, including the internet.</p></div>\n  </div>\n</section>\n\n<!-- 13 PACKET VISUALIZER -->\n<section class=\"chapter reveal\" id=\"sec-packetviz\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">13</span><span class=\"track\">Networking</span></div>\n  <h2>Packet Visualizer</h2>\n  <p class=\"dek\">Watch a request travel from client to server and back.</p>\n  <div class=\"panel\">\n    <div class=\"packet-path\" id=\"packet-path\">\n      <div class=\"line\"></div>\n      <div class=\"node\" style=\"left:0%;\">\ud83d\udcbb Client</div>\n      <div class=\"node\" style=\"left:23%;\">\ud83d\udd00 Switch</div>\n      <div class=\"node\" style=\"left:46%;\">\ud83d\udce1 Router</div>\n      <div class=\"node\" style=\"left:69%;\">\ud83c\udf10 Internet</div>\n      <div class=\"node\" style=\"left:88%;\">\ud83d\udda5 Server</div>\n      <div class=\"packet-dot\" id=\"packet-dot\" style=\"left:0%;\"></div>\n    </div>\n    <div class=\"center\"><button class=\"chip-btn active\" id=\"packet-play\">\u25b6 Send request</button></div>\n    <p class=\"small center mt-lg\" id=\"packet-msg\">Click play to send a packet from client to server and watch the return path.</p>\n  </div>\n</section>\n\n<!-- 14 IPv4, CIDR & SUBNETTING -->\n<section class=\"chapter reveal\" id=\"sec-ipv4\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">14</span><span class=\"track\">Networking</span></div>\n  <h2>IPv4 Addressing, CIDR &amp; Subnetting</h2>\n  <p class=\"dek\">Enter an IP and prefix length \u2014 every derived value updates live.</p>\n  <div class=\"panel\">\n    <div class=\"ip-octets\">\n      <input type=\"number\" min=\"0\" max=\"255\" value=\"10\" id=\"ip-o1\"><span>.</span>\n      <input type=\"number\" min=\"0\" max=\"255\" value=\"0\" id=\"ip-o2\"><span>.</span>\n      <input type=\"number\" min=\"0\" max=\"255\" value=\"1\" id=\"ip-o3\"><span>.</span>\n      <input type=\"number\" min=\"0\" max=\"255\" value=\"0\" id=\"ip-o4\">\n      <span>/</span><input type=\"number\" min=\"1\" max=\"32\" value=\"24\" id=\"ip-prefix\" style=\"width:50px;\">\n    </div>\n    <input type=\"range\" min=\"8\" max=\"30\" value=\"24\" id=\"ip-prefix-slider\" class=\"cidr-slider\">\n    <div class=\"ip-result-grid\" id=\"ip-results\"></div>\n    <p class=\"small mt-lg\" id=\"ip-class-info\"></p>\n  </div>\n  <table class=\"cmp mt-lg\">\n    <tr><th>Range</th><th>Type</th></tr>\n    <tr><td>10.0.0.0 \u2013 10.255.255.255</td><td>Private (RFC 1918)</td></tr>\n    <tr><td>172.16.0.0 \u2013 172.31.255.255</td><td>Private (RFC 1918)</td></tr>\n    <tr><td>192.168.0.0 \u2013 192.168.255.255</td><td>Private (RFC 1918)</td></tr>\n    <tr><td>127.0.0.0/8</td><td>Loopback</td></tr>\n    <tr><td>224.0.0.0 \u2013 239.255.255.255</td><td>Multicast</td></tr>\n  </table>\n</section>\n\n<!-- 15 ARP, ROUTING & SWITCHING -->\n<section class=\"chapter reveal\" id=\"sec-arprouting\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">15</span><span class=\"track\">Networking</span></div>\n  <h2>ARP, Routing &amp; Switching</h2>\n  <p class=\"dek\">Three mechanisms that get a packet from A to B on a local and routed network.</p>\n  <div class=\"grid grid-3\">\n    <div class=\"card\"><h4>\ud83d\udd0d ARP</h4><p>Resolves an IP address to a MAC address on the local segment before a frame can be sent.</p><button class=\"chip-btn active mt-lg\" id=\"arp-run\">Resolve 10.0.1.5</button><p class=\"small mt-lg\" id=\"arp-result\"></p></div>\n    <div class=\"card\"><h4>\ud83d\udce1 Routing</h4><p>A router forwards packets between networks using its routing table.</p>\n      <table class=\"console-table mt-lg\"><tr><th>Destination</th><th>Next Hop</th></tr><tr><td>10.0.1.0/24</td><td>local</td></tr><tr><td>0.0.0.0/0</td><td>10.0.0.1 (default)</td></tr></table>\n    </div>\n    <div class=\"card\"><h4>\ud83d\udd00 Switching</h4><p>A switch forwards frames within a segment using a learned MAC address table.</p>\n      <table class=\"console-table mt-lg\" id=\"mac-table\"></table>\n    </div>\n  </div>\n</section>\n\n<!-- 16 DNS, DHCP & NAT -->\n<section class=\"chapter reveal\" id=\"sec-dnsdhcpnat\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">16</span><span class=\"track\">Networking</span></div>\n  <h2>DNS, DHCP &amp; NAT</h2>\n  <h3>DNS resolution</h3>\n  <div class=\"panel\">\n    <div class=\"flow-steps\" id=\"dns-flow\"></div>\n    <div class=\"center mt-lg\"><button class=\"chip-btn active\" id=\"dns-play\">\u25b6 Resolve example.com</button></div>\n  </div>\n  <h3>DHCP lease</h3>\n  <div class=\"panel mt-lg\">\n    <div class=\"flow-steps\" id=\"dhcp-flow\"></div>\n    <div class=\"center mt-lg\"><button class=\"chip-btn active\" id=\"dhcp-play\">\u25b6 Request an IP (DORA)</button></div>\n  </div>\n  <h3>NAT translation table</h3>\n  <div class=\"panel mt-lg\">\n    <button class=\"chip-btn active\" id=\"nat-add\">\uff0b New outbound connection</button>\n    <table class=\"nat-table\"><thead><tr><th>Private IP:Port</th><th>Public IP:Port</th><th>Destination</th></tr></thead><tbody id=\"nat-tbody\"></tbody></table>\n  </div>\n</section>\n\n<!-- 17 TLS/SSL, HTTPS & SSH -->\n<section class=\"chapter reveal\" id=\"sec-tlsssh\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">17</span><span class=\"track\">Networking</span></div>\n  <h2>TLS/SSL, HTTP vs HTTPS &amp; SSH</h2>\n  <h3>TLS handshake</h3>\n  <div class=\"panel\">\n    <div class=\"flow-steps\" id=\"tls-flow\"></div>\n    <div class=\"center mt-lg\"><button class=\"chip-btn active\" id=\"tls-play\">\u25b6 Animate handshake</button></div>\n  </div>\n  <div class=\"grid grid-2 mt-lg\">\n    <div class=\"card\"><h4>HTTP</h4><p>Plaintext \u2014 port 80. Anyone on the path can read or modify the traffic.</p></div>\n    <div class=\"card\"><h4>HTTPS</h4><p>HTTP wrapped in TLS \u2014 port 443. Confidentiality and integrity in transit, and server authenticity via certificates.</p></div>\n  </div>\n  <h3>SSH secure connection</h3>\n  <div class=\"panel mt-lg\">\n    <div class=\"flow-steps\" id=\"ssh-flow\"></div>\n    <div class=\"center mt-lg\"><button class=\"chip-btn active\" id=\"ssh-play\">\u25b6 Connect via SSH key</button></div>\n  </div>\n  <h3>ICMP: ping &amp; traceroute</h3>\n  <div class=\"panel mt-lg\">\n    <button class=\"chip-btn active\" id=\"ping-run\">ping 8.8.8.8</button>\n    <button class=\"chip-btn\" id=\"trace-run\">traceroute 8.8.8.8</button>\n    <div class=\"terminal mt-lg\" style=\"max-width:100%;\"><div id=\"icmp-out\" style=\"padding:14px; font-family:var(--font-mono); font-size:12.5px; color:#c9f7d8; min-height:80px; white-space:pre-wrap;\"></div></div>\n  </div>\n</section>\n\n<!-- 18 TCP vs UDP, FIREWALLS & LB -->\n<section class=\"chapter reveal\" id=\"sec-tcpudp\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">18</span><span class=\"track\">Networking</span></div>\n  <h2>TCP vs UDP, Firewalls &amp; Load Balancing</h2>\n  <table class=\"cmp\">\n    <tr><th></th><th>TCP</th><th>UDP</th></tr>\n    <tr><td>Connection</td><td>Connection-oriented (3-way handshake)</td><td>Connectionless</td></tr>\n    <tr><td>Reliability</td><td>Guaranteed delivery, retransmission</td><td>Best-effort, no retransmission</td></tr>\n    <tr><td>Ordering</td><td>In-order delivery</td><td>No ordering guarantee</td></tr>\n    <tr><td>Latency</td><td>Higher (handshake + acks)</td><td>Lower</td></tr>\n    <tr><td>Use cases</td><td>HTTP, SSH, databases</td><td>DNS queries, video streaming, VoIP</td></tr>\n  </table>\n  <h3>Stateful vs stateless firewall</h3>\n  <div class=\"panel\">\n    <div class=\"cost-filters\"><button class=\"chip-btn active\" data-fw=\"stateful\">Stateful</button><button class=\"chip-btn\" data-fw=\"stateless\">Stateless</button></div>\n    <p class=\"small mt-lg\" id=\"fw-desc\"></p>\n    <button class=\"chip-btn active mt-lg\" id=\"fw-test\">Test: allow return traffic for an established connection</button>\n    <p class=\"small mt-lg\" id=\"fw-result\"></p>\n  </div>\n  <h3>Load balancer traffic simulator</h3>\n  <div class=\"panel mt-lg\">\n    <div class=\"cost-filters\"><button class=\"chip-btn active\" data-lb=\"rr\">Round Robin</button><button class=\"chip-btn\" data-lb=\"lc\">Least Connections</button><button class=\"chip-btn\" data-lb=\"ih\">IP Hash</button></div>\n    <button class=\"chip-btn active mt-lg\" id=\"lb-send\">Send 6 requests</button>\n    <div class=\"grid grid-3 mt-lg\" id=\"lb-backends\"></div>\n  </div>\n</section>\n<!-- 19 OCI CLOUD SHELL -->\n<section class=\"chapter reveal\" id=\"sec-cloudshell\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">19</span><span class=\"track\">Cloud Shell &amp; CLI</span></div>\n  <h2>OCI Cloud Shell</h2>\n  <p class=\"dek\">A browser-based terminal with the OCI CLI pre-authenticated and 5GB of persistent storage per region \u2014 no local install required.</p>\n  <div class=\"cloudshell\">\n    <div class=\"cloudshell-tb\"><span>Cloud Shell \u2014 region: us-ashburn-1</span><span class=\"cs-actions\"><span>\u2b06 Upload</span><span>\u2b07 Download</span><span>\ud83d\udcdd Editor</span></span></div>\n    <div id=\"cs-out\" style=\"padding:14px; font-family:var(--font-mono); font-size:12.5px; color:#c9f7d8; min-height:180px; white-space:pre-wrap;\"></div>\n    <div class=\"term-input-row\"><span>$</span><input id=\"cs-input\" type=\"text\" placeholder=\"try: oci os ns get\" autocomplete=\"off\"></div>\n  </div>\n  <div class=\"callout callout-tip\"><div class=\"ic\">\ud83c\udf93</div><div><b>Exam Tip</b>Cloud Shell sessions time out after a period of inactivity, but the 5GB home directory persists across sessions \u2014 code and config survive even though the compute behind it doesn't.</div></div>\n</section>\n\n<!-- 20 CLI CONFIG & AUTHENTICATION -->\n<section class=\"chapter reveal\" id=\"sec-cliauth\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">20</span><span class=\"track\">Cloud Shell &amp; CLI</span></div>\n  <h2>CLI Configuration &amp; Authentication</h2>\n  <p class=\"dek\">The CLI reads <span class=\"mono\">~/.oci/config</span> for a profile's region, user, and key fingerprint.</p>\n  <div class=\"config-editor\">\n[<span class=\"cv\">DEFAULT</span>]\n<span class=\"ck\">user</span>=<span class=\"cv\">ocid1.user.oc1..aaaaaaaa...</span>\n<span class=\"ck\">fingerprint</span>=<span class=\"cv\">a1:b2:c3:d4:e5:f6:...</span>\n<span class=\"ck\">key_file</span>=<span class=\"cv\">~/.oci/oci_api_key.pem</span>\n<span class=\"ck\">tenancy</span>=<span class=\"cv\">ocid1.tenancy.oc1..aaaaaaaa...</span>\n<span class=\"ck\">region</span>=<span class=\"cv\">us-ashburn-1</span> <span class=\"cc\"># default profile</span>\n  </div>\n  <h3>Authentication methods</h3>\n  <div class=\"grid grid-2 mt-lg\">\n    <div class=\"card\"><h4>API Keys / Config File</h4><p>A local RSA key pair; fingerprint + private key referenced from <span class=\"mono\">~/.oci/config</span>. Best for CLI/SDK use from your own machine.</p></div>\n    <div class=\"card\"><h4>Session Token</h4><p>Short-lived token from an SSO login (<span class=\"mono\">oci session authenticate</span>) \u2014 no long-lived key on disk.</p></div>\n    <div class=\"card\"><h4>Instance Principal</h4><p>A compute instance authenticates as itself, no embedded credentials \u2014 ideal for code running on OCI compute.</p></div>\n    <div class=\"card\"><h4>Resource Principal / Dynamic Group</h4><p>Non-compute resources (like Functions) authenticate via a Dynamic Group's matching rule, scoped by IAM policy.</p></div>\n  </div>\n  <h3>CLI troubleshooting</h3>\n  <div class=\"panel mt-lg\">\n    <div class=\"cost-filters\" id=\"clierr-btns\">\n      <button class=\"chip-btn active\" data-clierr=\"notauth\">NotAuthorizedOrNotFound</button>\n      <button class=\"chip-btn\" data-clierr=\"invalidconfig\">Invalid config file</button>\n      <button class=\"chip-btn\" data-clierr=\"sigerror\">Signature error</button>\n      <button class=\"chip-btn\" data-clierr=\"missingregion\">Missing region</button>\n      <button class=\"chip-btn\" data-clierr=\"expiredkey\">Expired/revoked key</button>\n    </div>\n    <p class=\"mono mt-lg\" style=\"color:var(--red-bright);\" id=\"clierr-text\"></p>\n    <p class=\"small mt-lg\" id=\"clierr-fix\"></p>\n  </div>\n</section>\n\n<!-- 21 CLI COMMAND SIMULATOR -->\n<section class=\"chapter reveal\" id=\"sec-clisim\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">21</span><span class=\"track\">Cloud Shell &amp; CLI</span></div>\n  <h2>CLI Command Simulator</h2>\n  <p class=\"dek\">Build a command using <span class=\"mono\">oci &lt;service&gt; &lt;resource&gt; &lt;action&gt;</span> and run it.</p>\n  <div class=\"panel\">\n    <div style=\"display:flex; gap:8px; flex-wrap:wrap;\">\n      <select class=\"mini-input\" id=\"clibuild-service\"><option value=\"iam\">iam</option><option value=\"compute\">compute</option><option value=\"network\">network</option><option value=\"os\">os</option></select>\n      <select class=\"mini-input\" id=\"clibuild-resource\"></select>\n      <select class=\"mini-input\" id=\"clibuild-action\"><option value=\"list\">list</option><option value=\"get\">get</option></select>\n      <button class=\"chip-btn active\" id=\"clibuild-run\">\u25b6 Run</button>\n    </div>\n    <p class=\"mono mt-lg\" style=\"color:var(--blue);\" id=\"clibuild-preview\">oci iam user list</p>\n    <div class=\"terminal mt-lg\" style=\"max-width:100%;\"><div id=\"clibuild-out\" style=\"padding:14px; font-family:var(--font-mono); font-size:12.5px; color:#c9f7d8; min-height:80px; white-space:pre-wrap;\"></div></div>\n  </div>\n</section>\n\n<!-- 22 REST API & STATUS CODES -->\n<section class=\"chapter reveal\" id=\"sec-restapi\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">22</span><span class=\"track\">REST &amp; SDK</span></div>\n  <h2>REST API &amp; Status Codes</h2>\n  <p class=\"dek\">The Console, CLI, and SDKs are all thin wrappers around the same REST API.</p>\n  <div class=\"rest-client\">\n    <div class=\"rest-url-row\">\n      <span class=\"rest-method active-get\" data-m=\"GET\">GET</span>\n      <span class=\"rest-method\" data-m=\"POST\">POST</span>\n      <span class=\"rest-method\" data-m=\"DELETE\">DELETE</span>\n      <input class=\"mini-input\" id=\"rest-url\" value=\"/20160918/instances?compartmentId=ocid1.compartment...\" style=\"flex:1;\">\n      <button class=\"chip-btn active\" id=\"rest-send\">Send</button>\n    </div>\n    <div class=\"rest-response\" id=\"rest-response\">Click Send to see a simulated response.</div>\n  </div>\n  <h3>Status codes</h3>\n  <div class=\"status-code-grid mt-lg\" id=\"status-grid\"></div>\n  <div class=\"cia-detail mt-lg\" id=\"status-detail\">Click a status code above.</div>\n</section>\n\n<!-- 23 SDK, SIGNING & COMPARISON -->\n<section class=\"chapter reveal\" id=\"sec-sdk\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">23</span><span class=\"track\">REST &amp; SDK</span></div>\n  <h2>OCI SDKs, Request Signing &amp; Comparison</h2>\n  <p class=\"dek\">Official SDKs exist for Python, Java, Go, .NET, Node.js, and Ruby \u2014 pick your language below.</p>\n  <div class=\"cost-filters\" id=\"sdk-lang-btns\">\n    <button class=\"chip-btn active\" data-lang=\"python\">Python</button><button class=\"chip-btn\" data-lang=\"java\">Java</button>\n    <button class=\"chip-btn\" data-lang=\"go\">Go</button><button class=\"chip-btn\" data-lang=\"node\">Node.js</button>\n  </div>\n  <div class=\"policy-editor\" id=\"sdk-code\" style=\"margin-top:12px;\"></div>\n\n  <h3>Request signing</h3>\n  <div class=\"panel mt-lg\">\n    <div class=\"flow-steps\" id=\"signing-flow\"></div>\n    <div class=\"center mt-lg\"><button class=\"chip-btn active\" id=\"signing-play\">\u25b6 Animate signing</button></div>\n  </div>\n\n  <h3>Console vs CLI vs SDK vs API</h3>\n  <table class=\"decision-matrix mt-lg\">\n    <tr><th></th><th>Console</th><th>CLI</th><th>SDK</th><th>REST API</th></tr>\n    <tr><td>Best for</td><td>Exploration, one-offs</td><td>Scripting, automation</td><td>Application integration</td><td>Custom tooling, any language</td></tr>\n    <tr><td>Learning curve</td><td>Lowest</td><td>Low</td><td>Medium</td><td>Highest</td></tr>\n    <tr><td>Automatable</td><td>No</td><td>Yes</td><td>Yes</td><td>Yes</td></tr>\n    <tr><td>Auth handling</td><td>Browser session</td><td>Config file</td><td>Config file / instance principal</td><td>Manual request signing</td></tr>\n  </table>\n</section>\n<!-- 24 CONSOLE SIMULATOR -->\n<section class=\"chapter reveal\" id=\"sec-console3\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">24</span><span class=\"track\">Hands-On Lab</span></div>\n  <h2>OCI Console Simulator</h2>\n  <p class=\"dek\">A simplified Compute/Networking console.</p>\n  <div class=\"console-sim\">\n    <div class=\"console-tb\"><div class=\"dots\"><span style=\"background:#ff5f57\"></span><span style=\"background:#febc2e\"></span><span style=\"background:#28c840\"></span></div><span class=\"small mono\">console.oracle-simulator.local/compute</span></div>\n    <div class=\"console-body\">\n      <div class=\"console-nav\">\n        <div class=\"active\" data-panel3=\"instances\">\ud83d\udda5 Instances</div>\n        <div data-panel3=\"vcns\">\ud83c\udf10 VCNs</div>\n        <div data-panel3=\"storage3\">\ud83d\udcbe Block Volumes</div>\n      </div>\n      <div class=\"console-main\">\n        <div class=\"console-panel3\" id=\"panel3-instances\">\n          <table class=\"console-table\"><thead><tr><th>Name</th><th>Shape</th><th>Public IP</th><th>State</th></tr></thead>\n          <tbody><tr><td>web-vm-01</td><td>VM.Standard.E4.Flex</td><td>140.238.10.5</td><td><span class=\"status-pill active\">Running</span></td></tr>\n          <tr><td>batch-vm-01</td><td>VM.Standard.E4.Flex</td><td>\u2014</td><td><span class=\"status-pill active\">Running</span></td></tr></tbody></table>\n        </div>\n        <div class=\"console-panel3\" id=\"panel3-vcns\" style=\"display:none;\">\n          <table class=\"console-table\"><thead><tr><th>VCN</th><th>CIDR</th><th>Subnets</th></tr></thead>\n          <tbody><tr><td>prod-vcn</td><td>10.0.0.0/16</td><td>3</td></tr></tbody></table>\n        </div>\n        <div class=\"console-panel3\" id=\"panel3-storage3\" style=\"display:none;\">\n          <table class=\"console-table\"><thead><tr><th>Volume</th><th>Size</th><th>Attached To</th></tr></thead>\n          <tbody><tr><td>web-vm-01-boot</td><td>50 GB</td><td>web-vm-01</td></tr></tbody></table>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- 25 LINUX + CLI TERMINAL -->\n<section class=\"chapter reveal\" id=\"sec-terminal3\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">25</span><span class=\"track\">Hands-On Lab</span></div>\n  <h2>Linux + OCI CLI Terminal</h2>\n  <p class=\"dek\">Combined terminal \u2014 supports both Linux commands and <span class=\"mono\">oci</span> CLI calls.</p>\n  <div class=\"terminal\">\n    <div class=\"terminal-tb\">bash + oci-cli \u2014 simulator</div>\n    <div id=\"term-out3\"></div>\n    <div class=\"term-input-row\"><span>$</span><input id=\"term-input3\" type=\"text\" placeholder=\"type: help\" autocomplete=\"off\"></div>\n  </div>\n  <p class=\"small mt-lg\">Try: <span class=\"mono\">help, pwd, ls, top, journalctl, oci compute instance list, oci network vcn list, oci iam compartment list, clear</span></p>\n</section>\n\n<!-- 26 TROUBLESHOOTING LAB -->\n<section class=\"chapter reveal\" id=\"sec-troubleshoot3\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">26</span><span class=\"track\">Hands-On Lab</span></div>\n  <h2>Troubleshooting Lab</h2>\n  <p class=\"dek\">Pick a failure scenario across Linux, networking, and API layers.</p>\n  <div class=\"cost-filters\" id=\"ts3-case-btns\">\n    <button class=\"chip-btn active\" data-case3=\"dns\">DNS Failure</button>\n    <button class=\"chip-btn\" data-case3=\"routing\">Routing Issue</button>\n    <button class=\"chip-btn\" data-case3=\"subnet\">Subnet Error</button>\n    <button class=\"chip-btn\" data-case3=\"firewall\">Firewall Block</button>\n    <button class=\"chip-btn\" data-case3=\"tls\">TLS Failure</button>\n    <button class=\"chip-btn\" data-case3=\"api\">API 401 Error</button>\n  </div>\n  <div class=\"panel\" id=\"ts3-panel\"></div>\n</section>\n\n<!-- 27 CHEAT SHEETS -->\n<section class=\"chapter reveal\" id=\"sec-cheatsheet3\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">27</span><span class=\"track\">Wrap-Up</span></div>\n  <h2>Cheat Sheets</h2>\n  <div class=\"grid grid-2\">\n    <div class=\"card\"><h4>Linux</h4><ul style=\"margin-left:16px;\"><li>rwx = 4+2+1; owner-group-others</li><li>chmod 777 = world-writable, avoid</li><li>Zombie = finished, not yet reaped by parent</li></ul></div>\n    <div class=\"card\"><h4>Networking</h4><ul style=\"margin-left:16px;\"><li>TCP = reliable/ordered; UDP = fast/best-effort</li><li>/24 = 256 addresses, 254 usable hosts</li><li>DNS: Browser \u2192 Cache \u2192 Root \u2192 TLD \u2192 Authoritative</li></ul></div>\n    <div class=\"card\"><h4>CLI</h4><ul style=\"margin-left:16px;\"><li>oci &lt;service&gt; &lt;resource&gt; &lt;action&gt;</li><li>Config lives at ~/.oci/config</li><li>Instance principals need no embedded key</li></ul></div>\n    <div class=\"card\"><h4>API / SDK</h4><ul style=\"margin-left:16px;\"><li>2xx success \u00b7 4xx client error \u00b7 5xx server error</li><li>429 = rate limited; back off and retry</li><li>Console/CLI/SDK are all wrappers over the same REST API</li></ul></div>\n  </div>\n  <table class=\"cmp mt-lg\"><tr><th>Command Reference</th></tr>\n    <tr><td class=\"mono\">oci os ns get</td></tr><tr><td class=\"mono\">oci iam user list</td></tr>\n    <tr><td class=\"mono\">oci iam compartment list</td></tr><tr><td class=\"mono\">oci compute instance list</td></tr>\n    <tr><td class=\"mono\">oci network vcn list</td></tr></table>\n</section>\n\n<!-- 28 FLASHCARDS -->\n<section class=\"chapter reveal\" id=\"sec-flashcards3\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">28</span><span class=\"track\">Wrap-Up</span></div>\n  <h2>Flash Cards</h2>\n  <p class=\"dek\">Click a card to flip it.</p>\n  <div class=\"flash-wrap\" id=\"flash-wrap3\"></div>\n</section>\n\n<!-- 29 QUIZ -->\n<section class=\"chapter reveal\" id=\"sec-quiz3\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">29</span><span class=\"track\">Wrap-Up</span></div>\n  <h2>Certification Readiness Quiz</h2>\n  <p class=\"dek\">20 scenario-style questions.</p>\n  <div id=\"quiz-wrap3\"></div>\n  <div class=\"panel center mt-lg\"><p>Your score: <b id=\"quiz-final-score3\" style=\"color:var(--red-bright); font-family:var(--font-display); font-size:20px;\">0 / 20</b></p></div>\n</section>\n\n<!-- 30 CERTIFICATE -->\n<section class=\"chapter reveal\" id=\"sec-cert3\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">30</span><span class=\"track\">Wrap-Up</span></div>\n  <h2>Completion &amp; Certificate Preview</h2>\n  <div class=\"center\" style=\"padding:20px 0 40px;\">\n    <div class=\"badge-circle\" id=\"badge-circle3\"><span id=\"badge-pct3\">0%</span></div>\n    <h3 id=\"badge-title3\">Keep going</h3>\n    <p class=\"small\" id=\"badge-sub3\">Complete every section and the quiz to preview your certificate.</p>\n  </div>\n  <div class=\"cert-frame\">\n    <p class=\"small\">ORACLE CLOUD INFRASTRUCTURE</p>\n    <h3>Certificate of Completion</h3>\n    <p class=\"small\">This certifies that</p>\n    <div class=\"cert-name\">Your Name</div>\n    <p class=\"small\">has completed <strong>Day 3: Linux, Networking, Cloud Shell &amp; CLI/SDK</strong></p>\n    <p class=\"small mt-lg\">Score: <span id=\"cert-score-display3\">0/20</span> \u00b7 Date: <span id=\"cert-date-display3\"></span></p>\n  </div>\n</section>\n\n</div>\n</main>\n</div>\n<footer>OCI Linux, Networking &amp; CLI/SDK \u2014 Day 3 \u00b7 Interactive Learning Platform \u00b7 Single self-contained HTML file \u00b7 No external dependencies</footer>\n\n\n\n\n\n\n\n\n\n\n", "js": "\nconst state = { quizScore:0, quizAnswered:0, quizTotal:0 };\ndocument.addEventListener('DOMContentLoaded', () => {\n  initParticles(); initProgressBar(); initSidebar(); initSearch(); initTheme(); initReveal();\n  initArchStack(); initShellTerminal(); initFsTree(); initNavLab();\n  initLinuxUsers(); initPermissions(); initChown();\n  initProcesses(); initSystemd(); initPackageManager(); initCron(); initLogs(); initEnvVars(); initBashScript();\n  initOSI(); initPacketViz(); initIPv4Calc(); initARPRoutingSwitching(); initDNSDHCPNAT(); initTLSSSH(); initTCPUDPFirewallLB();\n  initCloudShell(); initCliAuth(); initCliSim();\n  initRestApi(); initStatusCodes(); initSdk(); initSigningFlow();\n  initConsoleSim3(); initTerminal3(); initTroubleshootLab3();\n  initFlashcards3(); initQuiz3(); updateBadge3();\n});\nfunction initParticles(){\n  const c=document.getElementById('particles'); const ctx=c.getContext('2d'); let w,h,particles=[];\n  function resize(){ w=c.width=window.innerWidth; h=c.height=window.innerHeight; }\n  resize(); window.addEventListener('resize', resize);\n  const N=Math.min(60, Math.floor(window.innerWidth/24));\n  for(let i=0;i<N;i++) particles.push({x:Math.random()*w,y:Math.random()*h,r:Math.random()*1.6+0.4,vx:(Math.random()-0.5)*0.15,vy:(Math.random()-0.5)*0.15});\n  function tick(){ ctx.clearRect(0,0,w,h); ctx.fillStyle='rgba(199,70,52,0.5)';\n    particles.forEach(p=>{ p.x+=p.vx; p.y+=p.vy; if(p.x<0)p.x=w; if(p.x>w)p.x=0; if(p.y<0)p.y=h; if(p.y>h)p.y=0; ctx.beginPath(); ctx.arc(p.x,p.y,p.r,0,Math.PI*2); ctx.fill(); });\n    requestAnimationFrame(tick);\n  }\n  tick();\n}\nfunction initProgressBar(){\n  const bar=document.getElementById('progress-bar'); const heroProgress=document.getElementById('hero-progress');\n  window.addEventListener('scroll', ()=>{\n    const scrollTop=window.scrollY; const docH=document.documentElement.scrollHeight-window.innerHeight;\n    const pct=docH>0?(scrollTop/docH)*100:0;\n    bar.style.width=pct+'%'; if(heroProgress) heroProgress.textContent=Math.round(pct)+'%';\n    window.__lastScrollPct3=pct; updateBadge3(); highlightActiveNav();\n  }, {passive:true});\n}\nfunction highlightActiveNav(){\n  const sections=document.querySelectorAll('section.chapter'); let current=null;\n  sections.forEach(sec=>{ const rect=sec.getBoundingClientRect(); if(rect.top<160) current=sec.id; });\n  document.querySelectorAll('#sidebar a.nav-link').forEach(a=>a.classList.toggle('active', a.getAttribute('href')==='#'+current));\n}\nfunction initSidebar(){ const sb=document.getElementById('sidebar'); document.getElementById('sidebar-toggle').addEventListener('click', ()=>sb.classList.toggle('collapsed')); }\nfunction initSearch(){\n  const input=document.getElementById('search'); const results=document.getElementById('search-results'); const index=[];\n  document.querySelectorAll('section.chapter').forEach(sec=>{\n    const title=sec.querySelector('h2')?.textContent || sec.id;\n    sec.querySelectorAll('h3').forEach(h3=>index.push({label:h3.textContent, cat:title, href:'#'+sec.id}));\n    index.push({label:title, cat:'Section', href:'#'+sec.id});\n  });\n  input.addEventListener('input', ()=>{\n    const q=input.value.trim().toLowerCase(); if(!q){results.style.display='none'; return;}\n    const matches=index.filter(i=>i.label.toLowerCase().includes(q)).slice(0,8);\n    results.innerHTML=matches.map(m=>`<a href=\"${m.href}\"><span class=\"sr-cat\">${m.cat}</span>${m.label}</a>`).join('') || '<a style=\"cursor:default;\">No results</a>';\n    results.style.display='block';\n  });\n  document.addEventListener('click', e=>{ if(!document.getElementById('search-wrap').contains(e.target)) results.style.display='none'; });\n  results.addEventListener('click', ()=>setTimeout(()=>{results.style.display='none'; input.value='';},10));\n}\nfunction initTheme(){\n  const btn=document.getElementById('theme-toggle');\n  btn.addEventListener('click', ()=>{ const html=document.documentElement; const isDark=html.getAttribute('data-theme')!=='light'; html.setAttribute('data-theme', isDark?'light':'dark'); btn.textContent=isDark?'\u2600\ufe0f':'\ud83c\udf19'; });\n}\nfunction initReveal(){\n  const els=document.querySelectorAll('.reveal');\n  const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('in');}), {threshold:0.08});\n  els.forEach(el=>io.observe(el));\n}\n\n;\n\n/* ---------- linux architecture layers ---------- */\nfunction initArchStack(){\n  const layers = document.querySelectorAll('#arch-stack .arch-layer'); if(!layers.length) return;\n  const detail = document.getElementById('arch-detail');\n  const info = {\n    hardware: 'Hardware: CPU, RAM, disks, NICs \u2014 the physical resources everything above ultimately consumes.',\n    kernel: 'Kernel: the core program managing process scheduling, memory, filesystems, networking, and device drivers. Talks to hardware directly and exposes system calls upward.',\n    shell: 'Shell (bash, zsh, sh): a command interpreter that turns typed commands into system calls, and lets you script repeatable tasks.',\n    applications: 'Applications: programs like nginx, PostgreSQL, or your own code, built from GNU userland tools plus whatever you install.',\n    user: 'User: the human (or automation) issuing commands \u2014 everything below exists to serve this layer\\'s intent.'\n  };\n  layers.forEach(l=>{\n    l.addEventListener('click', ()=>{\n      layers.forEach(x=>x.classList.remove('active')); l.classList.add('active');\n      detail.textContent = info[l.dataset.l];\n    });\n  });\n}\n\n/* ---------- shell terminal with real simulated filesystem ---------- */\nfunction initShellTerminal(){\n  const out = document.getElementById('shell-out'); const input = document.getElementById('shell-input');\n  if(!input) return;\n  let fs = { '/': { type:'dir', children:{ 'docs': {type:'dir', children:{}}, 'readme.txt': {type:'file', content:'Welcome to the simulator.'} } } };\n  let cwd = ['/'];\n  let history = [];\n  function resolveDir(path){\n    let node = fs['/']; let parts = path==='/' ? [] : path.split('/').filter(Boolean);\n    for(const p of parts){ if(!node.children || !node.children[p] || node.children[p].type!=='dir') return null; node = node.children[p]; }\n    return node;\n  }\n  function cwdPath(){ return cwd.length<=1 ? '/' : '/'+cwd.slice(1).join('/'); }\n  function print(cmd, text){\n    const line = document.createElement('div');\n    const prompt = `[user@oci ${cwdPath()}]$`;\n    line.innerHTML = `<div class=\"cmdline\" style=\"color:#7db2ff;\">${esc(prompt+' '+cmd)}</div>` + (text!==undefined?`<div style=\"color:#c9f7d8; margin:2px 0 10px; white-space:pre-wrap;\">${esc(text)}</div>`:'');\n    out.appendChild(line); out.scrollTop = out.scrollHeight;\n    document.getElementById('shell-prompt-span').textContent = prompt;\n  }\n  function esc(s){ return s.replace(/[&<>]/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c])); }\n  print('', 'Simulated Oracle Linux 9 shell. Try: pwd, ls, cd docs, mkdir project, touch notes.txt, cat notes.txt');\n  input.addEventListener('keydown', e=>{\n    if(e.key!=='Enter') return;\n    const raw = input.value.trim(); input.value=''; if(!raw){ print(''); return; }\n    history.push(raw);\n    const [cmd, ...args] = raw.split(/\\s+/);\n    const dir = resolveDir(cwdPath());\n    switch(cmd){\n      case 'pwd': print(raw, cwdPath()); break;\n      case 'whoami': print(raw, 'opc'); break;\n      case 'hostname': print(raw, 'oci-instance-01'); break;\n      case 'date': print(raw, new Date().toString()); break;\n      case 'clear': out.innerHTML=''; break;\n      case 'history': print(raw, history.map((h,i)=>`${i+1}  ${h}`).join('\\n')); break;\n      case 'echo': print(raw, args.join(' ')); break;\n      case 'ls': {\n        const flags = args.filter(a=>a.startsWith('-')).join('');\n        const entries = Object.entries(dir.children||{});\n        if(flags.includes('l') || flags.includes('a')){\n          print(raw, entries.map(([n,v])=> `${v.type==='dir'?'drwxr-xr-x':'-rw-r--r--'}  opc  opc  ${n}`).join('\\n') || '(empty directory)');\n        } else {\n          print(raw, entries.map(([n,v])=> v.type==='dir'? n+'/' : n).join('   ') || '');\n        }\n        break;\n      }\n      case 'cd': {\n        const target = args[0];\n        if(!target || target==='~'){ cwd=['/']; print(raw); break; }\n        if(target==='..'){ if(cwd.length>1) cwd.pop(); print(raw); break; }\n        if(dir.children && dir.children[target] && dir.children[target].type==='dir'){ cwd.push(target); print(raw); }\n        else print(raw, `bash: cd: ${target}: No such file or directory`);\n        break;\n      }\n      case 'mkdir': {\n        const name = args[0];\n        if(!name){ print(raw,'mkdir: missing operand'); break; }\n        dir.children[name] = {type:'dir', children:{}};\n        print(raw); break;\n      }\n      case 'touch': {\n        const name = args[0];\n        if(!name){ print(raw,'touch: missing operand'); break; }\n        if(!dir.children[name]) dir.children[name] = {type:'file', content:''};\n        print(raw); break;\n      }\n      case 'cat': {\n        const name = args[0];\n        if(!name || !dir.children[name] || dir.children[name].type!=='file'){ print(raw, `cat: ${name||''}: No such file`); break; }\n        print(raw, dir.children[name].content || '(empty file)'); break;\n      }\n      case 'rm': {\n        const name = args[0];\n        if(!name || !dir.children[name]){ print(raw, `rm: cannot remove '${name||''}': No such file or directory`); break; }\n        delete dir.children[name]; print(raw); break;\n      }\n      case 'mv': case 'cp': {\n        const [src,dest] = args;\n        if(!src || !dest || !dir.children[src]){ print(raw, `${cmd}: missing file operand`); break; }\n        dir.children[dest] = JSON.parse(JSON.stringify(dir.children[src]));\n        if(cmd==='mv') delete dir.children[src];\n        print(raw); break;\n      }\n      case 'head': case 'tail': case 'less': {\n        const name = args[0];\n        if(!name || !dir.children[name]){ print(raw, `${cmd}: cannot open '${name||''}'`); break; }\n        print(raw, dir.children[name].content || '(empty file)'); break;\n      }\n      default: print(raw, `bash: ${cmd}: command not found`);\n    }\n  });\n}\n\n/* ---------- filesystem explorer (FHS) ---------- */\nfunction initFsTree(){\n  const wrap = document.getElementById('fs-tree'); if(!wrap) return;\n  const fhs = [\n    ['/','Root of the entire filesystem tree \u2014 everything else is mounted under it.'],\n    ['/bin','Essential user command binaries (ls, cp, cat) needed even in single-user mode.'],\n    ['/boot','Boot loader files and the kernel image.'],\n    ['/dev','Device files representing hardware (disks, terminals) as special files.'],\n    ['/etc','System-wide configuration files.'],\n    ['/home','Per-user home directories.'],\n    ['/lib','Shared libraries needed by binaries in /bin and /sbin.'],\n    ['/media','Mount points for removable media (USB, CD-ROM).'],\n    ['/mnt','Temporary mount points for admins to mount filesystems manually.'],\n    ['/opt','Optional third-party application packages.'],\n    ['/proc','Virtual filesystem exposing kernel/process information at runtime.'],\n    ['/root','Home directory for the root user (not to be confused with / ).'],\n    ['/run','Runtime data since last boot (PIDs, sockets).'],\n    ['/sbin','System binaries typically requiring root privileges.'],\n    ['/srv','Data for services provided by this system (e.g. web/ftp data).'],\n    ['/sys','Virtual filesystem exposing kernel and device information.'],\n    ['/tmp','Temporary files, usually cleared on reboot.'],\n    ['/usr','Secondary hierarchy for user utilities and applications.'],\n    ['/var','Variable data: logs, spool files, caches.'],\n  ];\n  wrap.innerHTML = fhs.map(([p])=>`<div class=\"fs-node\" data-p=\"${p}\">\ud83d\udcc1 ${p}</div>`).join('');\n  const detail = document.getElementById('fs-detail');\n  const map = Object.fromEntries(fhs);\n  wrap.querySelectorAll('.fs-node').forEach(n=> n.addEventListener('click', ()=> detail.textContent = map[n.dataset.p]));\n}\n\n/* ---------- navigation command lab ---------- */\nfunction initNavLab(){\n  const panel = document.getElementById('navlab-panel'); if(!panel) return;\n  const tasks = [\n    {task:'Print the current working directory', answer:['pwd']},\n    {task:'List all files, including hidden ones, in long format', answer:['ls -la','ls -al']},\n    {task:'Create a directory called \"backup\"', answer:['mkdir backup']},\n    {task:'Search recursively for the text \"ERROR\" inside files', answer:['grep -r ERROR', 'grep -r \"ERROR\"']},\n    {task:'Find every file named \"app.log\" under the current directory', answer:['find . -name app.log', 'find . -name \"app.log\"']},\n  ];\n  panel.innerHTML = tasks.map((t,i)=>`\n    <div class=\"field-row\">\n      <label>${i+1}. ${t.task}</label>\n      <div style=\"display:flex; gap:8px;\">\n        <input class=\"mini-input\" id=\"navlab-${i}\" style=\"flex:1; font-family:var(--font-mono);\" placeholder=\"type the command\">\n        <button class=\"chip-btn active\" data-check=\"${i}\">Check</button>\n      </div>\n      <p class=\"small\" id=\"navlab-fb-${i}\" style=\"margin-top:6px;\"></p>\n    </div>`).join('');\n  panel.querySelectorAll('[data-check]').forEach(btn=>{\n    btn.addEventListener('click', ()=>{\n      const i = btn.dataset.check;\n      const val = document.getElementById('navlab-'+i).value.trim().toLowerCase();\n      const fb = document.getElementById('navlab-fb-'+i);\n      if(tasks[i].answer.some(a=>a.toLowerCase()===val)){ fb.textContent='\u2713 Correct.'; fb.style.color='var(--green)'; }\n      else { fb.textContent='\u2717 Not quite \u2014 try again.'; fb.style.color='var(--red-bright)'; }\n    });\n  });\n}\n\n;\n\n/* ---------- linux user manager ---------- */\nfunction initLinuxUsers(){\n  const btn = document.getElementById('lu-add-btn'); if(!btn) return;\n  let uid = 1001;\n  let users = [{name:'opc', uid:1000, group:'opc', home:'/home/opc', status:'active'}];\n  function render(){\n    document.getElementById('lu-tbody').innerHTML = users.map((u,i)=>`\n      <tr><td>${u.name}</td><td>${u.uid}</td><td>${u.group}</td><td>${u.home}</td>\n      <td><span class=\"status-pill ${u.status==='active'?'active':'deleted'}\">${u.status}</span></td>\n      <td>\n        <span style=\"cursor:pointer; margin-right:8px;\" data-lock=\"${i}\">${u.status==='active'?'\ud83d\udd12 Lock':'\ud83d\udd13 Unlock'}</span>\n        <span style=\"cursor:pointer; color:var(--text-3);\" data-del=\"${i}\">\ud83d\uddd1</span>\n      </td></tr>`).join('');\n  }\n  document.getElementById('lu-add-btn').addEventListener('click', ()=>{\n    const inp = document.getElementById('lu-new-name'); const name = inp.value.trim();\n    if(!name) return;\n    users.push({name, uid:uid++, group:name, home:'/home/'+name, status:'active'});\n    inp.value=''; render();\n  });\n  document.getElementById('lu-tbody').addEventListener('click', e=>{\n    if(e.target.dataset.lock!==undefined){ const i=e.target.dataset.lock; users[i].status = users[i].status==='active'?'locked':'active'; render(); }\n    if(e.target.dataset.del!==undefined){ users.splice(e.target.dataset.del,1); render(); }\n  });\n  render();\n}\n\n/* ---------- permissions / octal / chmod ---------- */\nfunction initPermissions(){\n  const grid = document.getElementById('perm-grid'); if(!grid) return;\n  const rows = ['owner','group','others'];\n  const bits = {owner:{r:1,w:1,x:0}, group:{r:1,w:0,x:0}, others:{r:1,w:0,x:0}};\n  function render(){\n    let html = grid.querySelector('.ph') ? '<div class=\"ph\"></div><div class=\"ph\">Read</div><div class=\"ph\">Write</div><div class=\"ph\">Execute</div>' : '';\n    rows.forEach(role=>{\n      html += `<div style=\"text-transform:capitalize; font-weight:700;\">${role}</div>`;\n      ['r','w','x'].forEach(bit=>{\n        html += `<div><div class=\"perm-toggle ${bits[role][bit]?'on':''}\" data-role=\"${role}\" data-bit=\"${bit}\">${bit.toUpperCase()}</div></div>`;\n      });\n    });\n    grid.innerHTML = html;\n    let octals = [];\n    rows.forEach(role=>{\n      const val = bits[role].r*4 + bits[role].w*2 + bits[role].x*1;\n      octals.push(val);\n      document.getElementById('oct-'+role).textContent = val;\n    });\n    document.getElementById('chmod-output').textContent = `# chmod ${octals.join('')} notes.txt`;\n    const sym = rows.map(role=> (bits[role].r?'r':'-')+(bits[role].w?'w':'-')+(bits[role].x?'x':'-')).join('');\n    document.getElementById('perm-symbolic').innerHTML = `Symbolic: <span class=\"mono\">-${sym}</span>`;\n  }\n  render();\n  grid.addEventListener('click', e=>{\n    const t = e.target.closest('.perm-toggle'); if(!t) return;\n    const role = t.dataset.role, bit = t.dataset.bit;\n    bits[role][bit] = bits[role][bit] ? 0 : 1;\n    render();\n  });\n}\n\n/* ---------- chown & chmod 777 ---------- */\nfunction initChown(){\n  const btn = document.getElementById('chown-apply'); if(!btn) return;\n  btn.addEventListener('click', ()=>{\n    const val = document.getElementById('chown-input').value.trim();\n    const result = document.getElementById('chown-result');\n    if(!/^[\\w.-]+:[\\w.-]+$/.test(val)){ result.textContent = 'Expected form: owner:group (e.g. admin:ops)'; result.style.color='var(--amber)'; return; }\n    document.getElementById('chown-current').textContent = val.replace(':',' : ');\n    result.textContent = `\u2713 Ownership changed to ${val}.`; result.style.color='var(--green)';\n  });\n  document.getElementById('c777-simulate').addEventListener('click', ()=>{\n    document.getElementById('c777-result').innerHTML = '\ud83d\udca5 Any local user \u2014 and any process that achieves code execution on this host \u2014 can now overwrite <span class=\"mono\">deploy.sh</span>. An attacker who gets a low-privilege shell can silently replace it with malicious code that runs the next time it\\'s executed, often by a more privileged account (e.g. root via cron).';\n  });\n}\n\n;\n\n/* ---------- process manager ---------- */\nfunction initProcesses(){\n  const btn = document.getElementById('proc-spawn'); if(!btn) return;\n  let pid = 2001;\n  let procs = [{pid:1,ppid:0,cmd:'systemd',state:'running',cpu:0.1},{pid:842,ppid:1,cmd:'sshd',state:'running',cpu:0.2}];\n  const cmds = ['nginx: worker process','python3 app.py','node server.js','backup.sh','curl https://api'];\n  function render(){\n    document.getElementById('proc-tbody').innerHTML = procs.map((p,i)=>`\n      <tr><td>${p.pid}</td><td>${p.ppid}</td><td>${p.cmd}</td>\n      <td><span class=\"proc-state ${p.state}\">${p.state}</span></td><td>${p.cpu.toFixed(1)}%</td>\n      <td>\n        ${p.state==='running' ? `<span style=\"cursor:pointer; margin-right:8px;\" data-suspend=\"${i}\">\u23f8</span>` : `<span style=\"cursor:pointer; margin-right:8px;\" data-resume=\"${i}\">\u25b6</span>`}\n        <span style=\"cursor:pointer; color:var(--red-bright);\" data-kill=\"${i}\">\u2715 kill</span>\n      </td></tr>`).join('');\n  }\n  btn.addEventListener('click', ()=>{\n    procs.push({pid:pid++, ppid:1, cmd:cmds[Math.floor(Math.random()*cmds.length)], state:'running', cpu:Math.random()*20});\n    render();\n  });\n  document.getElementById('proc-tbody').addEventListener('click', e=>{\n    if(e.target.dataset.kill!==undefined) procs.splice(e.target.dataset.kill,1);\n    if(e.target.dataset.suspend!==undefined) procs[e.target.dataset.suspend].state='stopped';\n    if(e.target.dataset.resume!==undefined) procs[e.target.dataset.resume].state='running';\n    render();\n  });\n  render();\n}\n\n/* ---------- systemd dashboard ---------- */\nfunction initSystemd(){\n  const panel = document.getElementById('systemd-panel'); if(!panel) return;\n  let services = [{name:'httpd', status:'active', enabled:true},{name:'sshd', status:'active', enabled:true},{name:'nginx', status:'inactive', enabled:false}];\n  function render(){\n    panel.innerHTML = services.map((s,i)=>`\n      <div class=\"service-row\"><span><strong class=\"mono\">${s.name}.service</strong> \u2014 <span style=\"color:${s.status==='active'?'var(--green)':'var(--text-3)'}\">${s.status}</span> ${s.enabled?'\u00b7 enabled at boot':'\u00b7 disabled'}</span>\n      <span class=\"service-actions\">\n        <button class=\"chip-btn\" data-svc=\"${i}\" data-act=\"start\">start</button>\n        <button class=\"chip-btn\" data-svc=\"${i}\" data-act=\"stop\">stop</button>\n        <button class=\"chip-btn\" data-svc=\"${i}\" data-act=\"restart\">restart</button>\n        <button class=\"chip-btn\" data-svc=\"${i}\" data-act=\"${s.enabled?'disable':'enable'}\">${s.enabled?'disable':'enable'}</button>\n      </span></div>`).join('');\n  }\n  panel.addEventListener('click', e=>{\n    const idx = e.target.dataset.svc; if(idx===undefined) return;\n    const act = e.target.dataset.act; const s = services[idx];\n    if(act==='start'||act==='restart') s.status='active';\n    if(act==='stop') s.status='inactive';\n    if(act==='enable') s.enabled=true;\n    if(act==='disable') s.enabled=false;\n    render();\n  });\n  render();\n}\n\n/* ---------- package manager simulator ---------- */\nfunction initPackageManager(){\n  const out = document.getElementById('pkg-out'); if(!out) return;\n  let pm = 'dnf';\n  document.querySelectorAll('[data-pm]').forEach(btn=>{\n    btn.addEventListener('click', ()=>{ document.querySelectorAll('[data-pm]').forEach(b=>b.classList.remove('active')); btn.classList.add('active'); pm = btn.dataset.pm; });\n  });\n  document.querySelectorAll('[data-action]').forEach(btn=>{\n    btn.addEventListener('click', ()=>{\n      const name = document.getElementById('pkg-name').value.trim() || 'nginx';\n      const act = btn.dataset.action;\n      let cmd, output;\n      if(pm==='dnf'){\n        cmd = act==='install' ? `sudo dnf install -y ${name}` : act==='update' ? `sudo dnf update -y ${name}` : `sudo dnf remove -y ${name}`;\n        output = act==='install' ? `Last metadata expiration check...\\nDependencies resolved.\\nInstalling: ${name}\\nComplete!` : act==='update' ? `Dependencies resolved.\\nUpgrading: ${name}\\nComplete!` : `Removing: ${name}\\nComplete!`;\n      } else {\n        cmd = act==='install' ? `sudo apt install -y ${name}` : act==='update' ? `sudo apt update && sudo apt upgrade -y ${name}` : `sudo apt remove -y ${name}`;\n        output = act==='install' ? `Reading package lists... Done\\nSetting up ${name}...\\ndone.` : act==='update' ? `Reading package lists... Done\\n${name} is now the newest version.` : `Removing ${name}...\\ndone.`;\n      }\n      out.textContent = `$ ${cmd}\\n${output}`;\n    });\n  });\n}\n\n/* ---------- cron scheduler ---------- */\nfunction initCron(){\n  const btn = document.getElementById('cron-preview'); if(!btn) return;\n  btn.addEventListener('click', ()=>{\n    const expr = document.getElementById('cron-input').value.trim();\n    const wrap = document.getElementById('cron-timeline');\n    let intervalMin = 15;\n    const m = expr.match(/^\\*\\/(\\d+)/); if(m) intervalMin = parseInt(m[1]);\n    else if(expr.startsWith('0 * ')) intervalMin = 60;\n    const now = new Date();\n    let runs = [];\n    for(let i=1;i<=5;i++){ const t = new Date(now.getTime()+i*intervalMin*60000); runs.push(t.toTimeString().slice(0,5)); }\n    wrap.innerHTML = runs.map((r,i)=>(i>0?'<span class=\"flow-arrow\">\u2192</span>':'')+`<div class=\"flow-step\">${r}</div>`).join('');\n  });\n}\n\n;\n\n/* ---------- logs ---------- */\nfunction initLogs(){\n  const btns = document.querySelectorAll('[data-logcmd]'); if(!btns.length) return;\n  const out = document.getElementById('log-out');\n  const samples = {\n    'journalctl -u nginx': `-- Logs begin at Mon 2026-07-20 --\\nJul 24 09:12:01 oci-web nginx[1042]: Started nginx service\\nJul 24 09:15:33 oci-web nginx[1042]: 200 GET /health\\nJul 24 09:16:02 oci-web nginx[1042]: 502 GET /api/orders \u2014 upstream timeout`,\n    'tail -f /var/log/messages': `Jul 24 09:10:01 oci-web systemd: Starting Session 12 of user opc.\\nJul 24 09:11:44 oci-web sudo: opc : COMMAND=/bin/systemctl restart nginx\\nJul 24 09:16:02 oci-web kernel: TCP: out of memory -- consider tuning tcp_mem`,\n    'grep ERROR /var/log/app.log': `2026-07-24 09:14:20 ERROR OrderService: connection refused to db-primary:5432\\n2026-07-24 09:14:21 ERROR OrderService: retrying (1/3)\\n2026-07-24 09:14:25 ERROR OrderService: retrying (2/3)`\n  };\n  btns.forEach(b=>{\n    b.addEventListener('click', ()=>{\n      btns.forEach(x=>x.classList.remove('active')); b.classList.add('active');\n      out.textContent = `$ ${b.dataset.logcmd}\\n${samples[b.dataset.logcmd]}`;\n    });\n  });\n  btns[0].click();\n}\n\n/* ---------- environment variables ---------- */\nfunction initEnvVars(){\n  const btn = document.getElementById('env-append-btn'); if(!btn) return;\n  btn.addEventListener('click', ()=>{\n    const val = document.getElementById('env-append').value.trim();\n    if(!val) return;\n    const pathEl = document.getElementById('env-path');\n    pathEl.textContent = val + ':' + pathEl.textContent;\n    document.getElementById('env-append').value='';\n  });\n}\n\n/* ---------- bash script mini interpreter ---------- */\nfunction initBashScript(){\n  const btn = document.getElementById('bash-run'); if(!btn) return;\n  btn.addEventListener('click', ()=>{\n    const src = document.getElementById('bash-editor').value;\n    const outEl = document.getElementById('bash-out');\n    let output = [];\n    const vars = {};\n    const lines = src.split('\\n');\n    let i=0;\n    function interpolate(str){ return str.replace(/\\$(\\w+)/g, (m,v)=> vars[v] !== undefined ? vars[v] : m); }\n    while(i<lines.length){\n      let line = lines[i].trim();\n      if(!line || line.startsWith('#!') ) { i++; continue; }\n      const assign = line.match(/^(\\w+)=\"?([^\"]*)\"?$/);\n      const forLoop = line.match(/^for\\s+(\\w+)\\s+in\\s+(.+)$/);\n      const echoMatch = line.match(/^echo\\s+\"?(.*?)\"?$/);\n      const ifExists = line.match(/^if\\s+\\[\\s+-f\\s+\"?([\\w.]+)\"?\\s+\\]\\s*;?\\s*then$/);\n      if(assign){ vars[assign[1]] = assign[2]; i++; continue; }\n      if(forLoop){\n        const varName = forLoop[1]; const items = forLoop[2].trim().split(/\\s+/);\n        let bodyStart = i+2; let bodyLines = [];\n        let j = bodyStart;\n        while(j<lines.length && lines[j].trim()!=='done'){ bodyLines.push(lines[j]); j++; }\n        items.forEach(item=>{\n          vars[varName] = item;\n          bodyLines.forEach(bl=>{\n            const em = bl.trim().match(/^echo\\s+\"?(.*?)\"?$/);\n            if(em) output.push(interpolate(em[1]));\n          });\n        });\n        i = j+1; continue;\n      }\n      if(ifExists){\n        const fname = ifExists[1];\n        const fileExists = fname === 'notes.txt' ? false : true; // simulate: notes.txt not present by default\n        let j=i+1; let thenLines=[]; let elseLines=[]; let inElse=false;\n        while(j<lines.length && lines[j].trim()!=='fi'){\n          if(lines[j].trim()==='else'){ inElse=true; j++; continue; }\n          (inElse?elseLines:thenLines).push(lines[j]); j++;\n        }\n        const branch = fileExists ? thenLines : elseLines;\n        branch.forEach(bl=>{ const em=bl.trim().match(/^echo\\s+\"?(.*?)\"?$/); if(em) output.push(interpolate(em[1])); });\n        i=j+1; continue;\n      }\n      if(echoMatch){ output.push(interpolate(echoMatch[1])); i++; continue; }\n      i++;\n    }\n    outEl.textContent = '$ ./script.sh\\n' + output.join('\\n');\n  });\n}\n\n;\n\n/* ---------- OSI layers ---------- */\nfunction initOSI(){\n  const layers = document.querySelectorAll('#osi-stack .osi-layer'); if(!layers.length) return;\n  const detail = document.getElementById('osi-detail');\n  const info = {\n    physical: 'Physical (L1): raw bits over cable, fiber, or radio \u2014 voltages, light pulses, radio waves.',\n    datalink: 'Data Link (L2): frames and MAC addresses \u2014 switches operate here.',\n    network: 'Network (L3): IP addresses and routing between networks \u2014 routers operate here.',\n    transport: 'Transport (L4): TCP/UDP \u2014 ports, reliability, ordering, segmentation.',\n    session: 'Session (L5): establishes, manages, and tears down sessions between applications.',\n    presentation: 'Presentation (L6): data translation, encryption, compression (e.g. TLS, character encoding).',\n    application: 'Application (L7): what the user/programs actually interact with \u2014 HTTP, DNS, SSH.'\n  };\n  layers.forEach(l=> l.addEventListener('click', ()=>{ layers.forEach(x=>x.classList.remove('active')); l.classList.add('active'); detail.textContent = info[l.dataset.o]; }));\n}\n\n/* ---------- packet visualizer ---------- */\nfunction initPacketViz(){\n  const btn = document.getElementById('packet-play'); if(!btn) return;\n  const dot = document.getElementById('packet-dot'); const msg = document.getElementById('packet-msg');\n  const stops = [0,23,46,69,88];\n  const labels = ['Leaving client','Through switch','Through router','Crossing the internet','Arrived at server'];\n  btn.addEventListener('click', ()=>{\n    let i=0;\n    function step(){\n      dot.style.left = stops[i]+'%';\n      msg.textContent = labels[i];\n      i++;\n      if(i<stops.length) setTimeout(step, 700);\n      else setTimeout(()=>{\n        msg.textContent = 'Server processed the request \u2014 now returning the response along the same path.';\n        let j = stops.length-1;\n        function back(){ dot.style.left = stops[j]+'%'; j--; if(j>=0) setTimeout(back,500); else msg.textContent='\u2713 Round trip complete.'; }\n        back();\n      }, 700);\n    }\n    step();\n  });\n}\n\n/* ---------- IPv4 / CIDR calculator ---------- */\nfunction initIPv4Calc(){\n  const slider = document.getElementById('ip-prefix-slider'); if(!slider) return;\n  const octets = ['ip-o1','ip-o2','ip-o3','ip-o4'].map(id=>document.getElementById(id));\n  const prefixInput = document.getElementById('ip-prefix');\n  function ipToInt(a,b,c,d){ return ((a<<24)>>>0)+(b<<16)+(c<<8)+d; }\n  function intToIp(n){ return [(n>>>24)&255,(n>>>16)&255,(n>>>8)&255,n&255].join('.'); }\n  function calc(){\n    const [a,b,c,d] = octets.map(o=>Math.max(0,Math.min(255,parseInt(o.value)||0)));\n    let prefix = Math.max(1,Math.min(32,parseInt(prefixInput.value)||24));\n    slider.value = prefix; prefixInput.value = prefix;\n    const ipInt = ipToInt(a,b,c,d);\n    const maskInt = prefix===0 ? 0 : (0xFFFFFFFF << (32-prefix)) >>> 0;\n    const network = (ipInt & maskInt) >>> 0;\n    const broadcast = (network | (~maskInt >>> 0)) >>> 0;\n    const totalHosts = Math.pow(2,32-prefix);\n    const usable = Math.max(0, totalHosts-2);\n    const octClass = a<128 ? 'A' : a<192 ? 'B' : a<224 ? 'C' : a<240 ? 'D (Multicast)' : 'E (Reserved)';\n    document.getElementById('ip-results').innerHTML = `\n      <div class=\"ip-result-item\">Network Address<b>${intToIp(network)}</b></div>\n      <div class=\"ip-result-item\">Broadcast Address<b>${intToIp(broadcast)}</b></div>\n      <div class=\"ip-result-item\">Subnet Mask<b>${intToIp(maskInt)}</b></div>\n      <div class=\"ip-result-item\">Total Addresses<b>${totalHosts}</b></div>\n      <div class=\"ip-result-item\">Usable Hosts<b>${usable}</b></div>\n      <div class=\"ip-result-item\">First / Last Usable<b>${usable>0?intToIp(network+1)+' \u2013 '+intToIp(broadcast-1):'\u2014'}</b></div>\n    `;\n    document.getElementById('ip-class-info').textContent = `Historical class: ${octClass}. (Modern networks use CIDR, not classful addressing \u2014 this is shown for exam context.)`;\n  }\n  octets.forEach(o=>o.addEventListener('input', calc));\n  prefixInput.addEventListener('input', calc);\n  slider.addEventListener('input', ()=>{ prefixInput.value = slider.value; calc(); });\n  calc();\n}\n\n/* ---------- ARP, routing, switching ---------- */\nfunction initARPRoutingSwitching(){\n  const btn = document.getElementById('arp-run'); if(!btn) return;\n  btn.addEventListener('click', ()=>{\n    document.getElementById('arp-result').innerHTML = `ARP request broadcast: \"Who has 10.0.1.5?\"<br>Reply: 10.0.1.5 is at <span class=\"mono\">02:1a:3f:9c:88:01</span><br>Cached in local ARP table.`;\n  });\n  const mac = document.getElementById('mac-table');\n  const entries = [['02:1a:3f:9c:88:01','port 1'],['02:1a:3f:9c:88:02','port 2'],['02:1a:3f:9c:88:03','port 3']];\n  mac.innerHTML = '<tr><th>MAC</th><th>Port</th></tr>'+entries.map(([m,p])=>`<tr><td class=\"mono\">${m}</td><td>${p}</td></tr>`).join('');\n}\n\n/* ---------- DNS / DHCP / NAT ---------- */\nfunction initDNSDHCPNAT(){\n  const dnsWrap = document.getElementById('dns-flow'); if(!dnsWrap) return;\n  const dnsSteps = ['Browser Cache','OS Resolver','Recursive Resolver','Root Server','TLD Server (.com)','Authoritative Server','Answer: 93.184.216.34'];\n  dnsWrap.innerHTML = dnsSteps.map((s,i)=>(i>0?'<span class=\"flow-arrow\">\u2192</span>':'')+`<div class=\"flow-step\">${s}</div>`).join('');\n  document.getElementById('dns-play').addEventListener('click', ()=>{\n    const els = dnsWrap.querySelectorAll('.flow-step'); els.forEach(e=>e.classList.remove('lit'));\n    dnsSteps.forEach((s,i)=> setTimeout(()=>els[i].classList.add('lit'), i*400));\n  });\n\n  const dhcpWrap = document.getElementById('dhcp-flow');\n  const dhcpSteps = ['Discover (client broadcasts)','Offer (server proposes IP)','Request (client accepts)','Acknowledge (lease confirmed)'];\n  dhcpWrap.innerHTML = dhcpSteps.map((s,i)=>(i>0?'<span class=\"flow-arrow\">\u2192</span>':'')+`<div class=\"flow-step\">${s}</div>`).join('');\n  document.getElementById('dhcp-play').addEventListener('click', ()=>{\n    const els = dhcpWrap.querySelectorAll('.flow-step'); els.forEach(e=>e.classList.remove('lit'));\n    dhcpSteps.forEach((s,i)=> setTimeout(()=>els[i].classList.add('lit'), i*450));\n  });\n\n  const natBody = document.getElementById('nat-tbody');\n  let natEntries = [['10.0.1.15:51422','140.238.10.5:33001','142.250.80.14:443']];\n  function renderNat(){ natBody.innerHTML = natEntries.map(([p,pub,dst])=>`<tr><td>${p}</td><td>${pub}</td><td>${dst}</td></tr>`).join(''); }\n  document.getElementById('nat-add').addEventListener('click', ()=>{\n    const priv = `10.0.1.${Math.floor(Math.random()*250)+2}:${40000+Math.floor(Math.random()*9000)}`;\n    const pub = `140.238.10.5:${33000+Math.floor(Math.random()*900)}`;\n    const dst = ['142.250.80.14:443','93.184.216.34:443','151.101.1.140:443'][Math.floor(Math.random()*3)];\n    natEntries.push([priv,pub,dst]); renderNat();\n  });\n  renderNat();\n}\n\n/* ---------- TLS, SSH, ICMP ---------- */\nfunction initTLSSSH(){\n  const tlsWrap = document.getElementById('tls-flow'); if(!tlsWrap) return;\n  const tlsSteps = ['Client Hello','Server Hello + Certificate','Client verifies cert','Key exchange','Session keys derived','Encrypted channel open'];\n  tlsWrap.innerHTML = tlsSteps.map((s,i)=>(i>0?'<span class=\"flow-arrow\">\u2192</span>':'')+`<div class=\"flow-step\">${s}</div>`).join('');\n  document.getElementById('tls-play').addEventListener('click', ()=>{\n    const els = tlsWrap.querySelectorAll('.flow-step'); els.forEach(e=>e.classList.remove('lit'));\n    tlsSteps.forEach((s,i)=> setTimeout(()=>els[i].classList.add('lit'), i*400));\n  });\n\n  const sshWrap = document.getElementById('ssh-flow');\n  const sshSteps = ['TCP connect :22','Server presents host key','Client verifies known_hosts','Key exchange (Diffie-Hellman)','Client authenticates with private key','Shell session established'];\n  sshWrap.innerHTML = sshSteps.map((s,i)=>(i>0?'<span class=\"flow-arrow\">\u2192</span>':'')+`<div class=\"flow-step\">${s}</div>`).join('');\n  document.getElementById('ssh-play').addEventListener('click', ()=>{\n    const els = sshWrap.querySelectorAll('.flow-step'); els.forEach(e=>e.classList.remove('lit'));\n    sshSteps.forEach((s,i)=> setTimeout(()=>els[i].classList.add('lit'), i*400));\n  });\n\n  const icmpOut = document.getElementById('icmp-out');\n  document.getElementById('ping-run').addEventListener('click', ()=>{\n    icmpOut.textContent = `PING 8.8.8.8 (8.8.8.8): 56 data bytes\\n64 bytes from 8.8.8.8: icmp_seq=0 ttl=115 time=11.2 ms\\n64 bytes from 8.8.8.8: icmp_seq=1 ttl=115 time=10.8 ms\\n64 bytes from 8.8.8.8: icmp_seq=2 ttl=115 time=12.1 ms\\n\\n--- 8.8.8.8 ping statistics ---\\n3 packets transmitted, 3 received, 0% packet loss`;\n  });\n  document.getElementById('trace-run').addEventListener('click', ()=>{\n    icmpOut.textContent = `traceroute to 8.8.8.8, 30 hops max\\n 1  10.0.0.1 (gateway)      1.1 ms\\n 2  140.91.x.x (ISP edge)   4.3 ms\\n 3  72.14.x.x (transit)     8.7 ms\\n 4  8.8.8.8 (google)       11.2 ms`;\n  });\n}\n\n/* ---------- TCP/UDP, firewall, load balancer ---------- */\nfunction initTCPUDPFirewallLB(){\n  const fwBtns = document.querySelectorAll('[data-fw]'); if(!fwBtns.length) return;\n  const fwDesc = document.getElementById('fw-desc');\n  const desc = { stateful: 'Stateful firewalls track connection state \u2014 once an outbound request is allowed, the matching return traffic is automatically permitted.', stateless: 'Stateless firewalls evaluate every packet independently against static rules \u2014 return traffic needs its own explicit allow rule.' };\n  let fwMode = 'stateful';\n  fwBtns.forEach(b=> b.addEventListener('click', ()=>{ fwBtns.forEach(x=>x.classList.remove('active')); b.classList.add('active'); fwMode=b.dataset.fw; fwDesc.textContent = desc[fwMode]; }));\n  fwDesc.textContent = desc.stateful;\n  document.getElementById('fw-test').addEventListener('click', ()=>{\n    const result = document.getElementById('fw-result');\n    if(fwMode==='stateful'){ result.textContent = '\u2713 Return traffic automatically allowed \u2014 the firewall recognized it belongs to an established outbound connection.'; result.style.color='var(--green)'; }\n    else { result.textContent = '\u2717 Blocked \u2014 no explicit inbound rule exists for this return traffic; stateless firewalls need one written per direction.'; result.style.color='var(--red-bright)'; }\n  });\n\n  const lbWrap = document.getElementById('lb-backends'); let lbMode = 'rr';\n  const backends = [{name:'backend-1', conns:0, count:0},{name:'backend-2', conns:0, count:0},{name:'backend-3', conns:0, count:0}];\n  function renderLB(){\n    lbWrap.innerHTML = backends.map(b=>`<div class=\"card\"><h4>${b.name}</h4><p>Requests received: <strong>${b.count}</strong></p></div>`).join('');\n  }\n  document.querySelectorAll('[data-lb]').forEach(b=> b.addEventListener('click', ()=>{ document.querySelectorAll('[data-lb]').forEach(x=>x.classList.remove('active')); b.classList.add('active'); lbMode=b.dataset.lb; }));\n  document.getElementById('lb-send').addEventListener('click', ()=>{\n    backends.forEach(b=>{b.count=0;});\n    let rrIndex=0;\n    for(let i=0;i<6;i++){\n      let chosen;\n      if(lbMode==='rr'){ chosen = backends[rrIndex % backends.length]; rrIndex++; }\n      else if(lbMode==='lc'){ chosen = backends.reduce((a,b)=> a.conns<=b.conns?a:b); }\n      else { chosen = backends[i % backends.length]; } // simplified ip-hash simulation\n      chosen.count++; chosen.conns++;\n    }\n    renderLB();\n  });\n  renderLB();\n}\n\n;\n\n/* ---------- OCI Cloud Shell ---------- */\nfunction initCloudShell(){\n  const input = document.getElementById('cs-input'); if(!input) return;\n  const out = document.getElementById('cs-out');\n  const responses = {\n    'oci os ns get': `{\\n  \"data\": \"axzs9frtpxxx\"\\n}`,\n    'oci iam compartment list': `{\\n  \"data\": [{\"name\": \"Production\", \"id\": \"ocid1.compartment.oc1..aaa1\"}, {\"name\": \"Dev\", \"id\": \"ocid1.compartment.oc1..aaa2\"}]\\n}`,\n    'ls': 'notes.txt  scripts/  config.json',\n    'pwd': '/home/opc'\n  };\n  function esc(s){ return s.replace(/[&<>]/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c])); }\n  out.innerHTML = 'Cloud Shell ready. 5GB persistent storage mounted at /home/opc.\\n\\n';\n  input.addEventListener('keydown', e=>{\n    if(e.key!=='Enter') return;\n    const cmd = input.value.trim(); input.value=''; if(!cmd) return;\n    const line = document.createElement('div');\n    line.innerHTML = `<span style=\"color:#7db2ff;\">$ ${esc(cmd)}</span>\\n<span>${esc(responses[cmd] || 'command executed (simulated).')}</span>\\n`;\n    out.appendChild(line); out.scrollTop = out.scrollHeight;\n  });\n}\n\n/* ---------- CLI auth troubleshooting ---------- */\nfunction initCliAuth(){\n  const btns = document.querySelectorAll('[data-clierr]'); if(!btns.length) return;\n  const errText = document.getElementById('clierr-text'); const errFix = document.getElementById('clierr-fix');\n  const cases = {\n    notauth: {e:'ServiceError: NotAuthorizedOrNotFound (Status 404)', f:'Fix: check the IAM policy grants the calling principal the needed verb on this resource type in this compartment \u2014 this error deliberately hides whether the resource exists or you lack permission.'},\n    invalidconfig: {e:'Error: Invalid config file, key_file /home/user/.oci/key.pem does not exist', f:'Fix: verify the key_file path in ~/.oci/config points to an actual private key file, and that the path uses the correct home directory.'},\n    sigerror: {e:'ServiceError: The required information to complete authentication was not provided or was incorrect. (Status 401)', f:'Fix: the fingerprint in your config likely doesn\\'t match the uploaded public key \u2014 re-upload the public key or fix the fingerprint value.'},\n    missingregion: {e:'Error: Missing config value: region', f:'Fix: add a region= line to your profile in ~/.oci/config, or pass --region on the command line.'},\n    expiredkey: {e:'ServiceError: The API signing key has been deleted or deactivated. (Status 401)', f:'Fix: generate a new API key pair, upload the new public key in the Console, and update key_file/fingerprint locally.'}\n  };\n  btns.forEach(b=>{\n    b.addEventListener('click', ()=>{\n      btns.forEach(x=>x.classList.remove('active')); b.classList.add('active');\n      const c = cases[b.dataset.clierr]; errText.textContent = c.e; errFix.textContent = c.f;\n    });\n  });\n  btns[0].click();\n}\n\n/* ---------- CLI command builder ---------- */\nfunction initCliSim(){\n  const svc = document.getElementById('clibuild-service'); if(!svc) return;\n  const resource = document.getElementById('clibuild-resource'); const action = document.getElementById('clibuild-action');\n  const resources = { iam:['user','group','compartment','policy'], compute:['instance','image'], network:['vcn','subnet'], os:['ns','bucket'] };\n  function fillResources(){\n    resource.innerHTML = resources[svc.value].map(r=>`<option value=\"${r}\">${r}</option>`).join('');\n    updatePreview();\n  }\n  function updatePreview(){\n    document.getElementById('clibuild-preview').textContent = `oci ${svc.value} ${resource.value} ${action.value}`;\n  }\n  svc.addEventListener('change', fillResources);\n  resource.addEventListener('change', updatePreview);\n  action.addEventListener('change', updatePreview);\n  fillResources();\n  document.getElementById('clibuild-run').addEventListener('click', ()=>{\n    const cmd = `oci ${svc.value} ${resource.value} ${action.value}`;\n    document.getElementById('clibuild-out').textContent = `$ ${cmd}\\n{\\n  \"data\": [\\n    { \"display-name\": \"example-${resource.value}-1\" },\\n    { \"display-name\": \"example-${resource.value}-2\" }\\n  ]\\n}`;\n  });\n}\n\n;\n\n/* ---------- REST client ---------- */\nfunction initRestApi(){\n  const btn = document.getElementById('rest-send'); if(!btn) return;\n  let method = 'GET';\n  document.querySelectorAll('.rest-method').forEach(m=>{\n    m.addEventListener('click', ()=>{\n      document.querySelectorAll('.rest-method').forEach(x=>x.className='rest-method');\n      method = m.dataset.m;\n      m.classList.add('active-'+method.toLowerCase());\n    });\n  });\n  btn.addEventListener('click', ()=>{\n    const resp = document.getElementById('rest-response');\n    if(method==='GET') resp.textContent = `HTTP/1.1 200 OK\\n{\\n  \"data\": [\\n    {\"id\": \"ocid1.instance.oc1..aaa1\", \"lifecycleState\": \"RUNNING\"},\\n    {\"id\": \"ocid1.instance.oc1..aaa2\", \"lifecycleState\": \"STOPPED\"}\\n  ]\\n}`;\n    else if(method==='POST') resp.textContent = `HTTP/1.1 201 Created\\n{\\n  \"id\": \"ocid1.instance.oc1..aaa3\",\\n  \"lifecycleState\": \"PROVISIONING\"\\n}`;\n    else resp.textContent = `HTTP/1.1 204 No Content`;\n  });\n}\n\n/* ---------- status codes ---------- */\nfunction initStatusCodes(){\n  const grid = document.getElementById('status-grid'); if(!grid) return;\n  const codes = [\n    [200,'OK \u2014 request succeeded','2xx'],[201,'Created \u2014 resource was created','2xx'],[204,'No Content \u2014 succeeded, nothing to return','2xx'],\n    [400,'Bad Request \u2014 malformed request body/params','4xx'],[401,'Unauthorized \u2014 authentication failed or missing','4xx'],\n    [403,'Forbidden \u2014 authenticated but not authorized','4xx'],[404,'Not Found \u2014 resource doesn\\'t exist (or you lack access)','4xx'],\n    [409,'Conflict \u2014 resource state conflict (e.g. already exists)','4xx'],[429,'Too Many Requests \u2014 rate limited, back off and retry','4xx'],\n    [500,'Internal Server Error \u2014 unexpected failure on the server','5xx']\n  ];\n  grid.innerHTML = codes.map(([c,d,cls])=>`<div class=\"status-card status-${cls}\" data-c=\"${c}\"><div class=\"code\">${c}</div></div>`).join('');\n  const detail = document.getElementById('status-detail');\n  const map = Object.fromEntries(codes.map(([c,d])=>[c,d]));\n  grid.querySelectorAll('.status-card').forEach(card=> card.addEventListener('click', ()=> detail.textContent = map[card.dataset.c]));\n}\n\n/* ---------- SDK snippets ---------- */\nfunction initSdk(){\n  const btns = document.querySelectorAll('#sdk-lang-btns .chip-btn'); if(!btns.length) return;\n  const out = document.getElementById('sdk-code');\n  const snippets = {\n    python: `<span class=\"ck\">import</span> oci\\n\\nconfig = oci.config.from_file()\\nidentity = oci.identity.IdentityClient(config)\\nusers = identity.list_users(compartment_id=config[<span class=\"cv\">\"tenancy\"</span>])\\n<span class=\"ck\">print</span>(users.data)`,\n    java: `ConfigFileReader.ConfigFile configFile = ConfigFileReader.parseDefault();\\nAuthenticationDetailsProvider provider =\\n  <span class=\"ck\">new</span> ConfigFileAuthenticationDetailsProvider(configFile);\\nIdentityClient client = <span class=\"ck\">new</span> IdentityClient(provider);\\nListUsersResponse resp = client.listUsers(ListUsersRequest.builder().build());`,\n    go: `config := common.DefaultConfigProvider()\\nclient, _ := identity.NewIdentityClientWithConfigurationProvider(config)\\nresp, _ := client.ListUsers(context.Background(), identity.ListUsersRequest{})\\nfmt.Println(resp.Items)`,\n    node: `<span class=\"ck\">const</span> identity = require(<span class=\"cv\">\"oci-identity\"</span>);\\n<span class=\"ck\">const</span> common = require(<span class=\"cv\">\"oci-common\"</span>);\\n<span class=\"ck\">const</span> provider = <span class=\"ck\">new</span> common.ConfigFileAuthenticationDetailProvider();\\n<span class=\"ck\">const</span> client = <span class=\"ck\">new</span> identity.IdentityClient({ authenticationDetailProvider: provider });\\n<span class=\"ck\">const</span> resp = <span class=\"ck\">await</span> client.listUsers({ compartmentId: provider.getTenantId() });`\n  };\n  function render(lang){ out.innerHTML = snippets[lang]; }\n  btns.forEach(b=> b.addEventListener('click', ()=>{ btns.forEach(x=>x.classList.remove('active')); b.classList.add('active'); render(b.dataset.lang); }));\n  render('python');\n}\n\n/* ---------- request signing flow ---------- */\nfunction initSigningFlow(){\n  const wrap = document.getElementById('signing-flow'); if(!wrap) return;\n  const steps = ['Build request','Compute SHA-256 body digest','Assemble signing string','Sign with RSA private key','Attach Authorization header','Send to OCI API'];\n  wrap.innerHTML = steps.map((s,i)=>(i>0?'<span class=\"flow-arrow\">\u2192</span>':'')+`<div class=\"flow-step\">${s}</div>`).join('');\n  document.getElementById('signing-play').addEventListener('click', ()=>{\n    const els = wrap.querySelectorAll('.flow-step'); els.forEach(e=>e.classList.remove('lit'));\n    steps.forEach((s,i)=> setTimeout(()=>els[i].classList.add('lit'), i*400));\n  });\n}\n\n/* ---------- console simulator 3 ---------- */\nfunction initConsoleSim3(){\n  const nav = document.querySelectorAll('.console-nav div[data-panel3]'); if(!nav.length) return;\n  nav.forEach(item=>{\n    item.addEventListener('click', ()=>{\n      nav.forEach(n=>n.classList.remove('active')); item.classList.add('active');\n      document.querySelectorAll('.console-panel3').forEach(p=>p.style.display='none');\n      document.getElementById('panel3-'+item.dataset.panel3).style.display='';\n    });\n  });\n}\n\n;\n\n/* ---------- combined linux + cli terminal ---------- */\nfunction initTerminal3(){\n  const out = document.getElementById('term-out3'); const input = document.getElementById('term-input3'); if(!input) return;\n  const responses = {\n    'help': `Linux commands: pwd, ls, top, journalctl\\nOCI CLI: oci compute instance list, oci network vcn list, oci iam compartment list\\nclear`,\n    'pwd': '/home/opc',\n    'ls': 'scripts/  app.log  config.yaml',\n    'top': `PID   USER  %CPU  %MEM  COMMAND\\n1042  opc   12.3  2.1   nginx\\n2091  opc   4.5   1.2   python3`,\n    'journalctl': `-- Logs begin --\\nJul 24 09:12:01 nginx[1042]: Started nginx service\\nJul 24 09:16:02 nginx[1042]: 502 GET /api/orders`,\n    'oci compute instance list': `{ \"data\": [{\"display-name\": \"web-vm-01\", \"lifecycle-state\": \"RUNNING\"}] }`,\n    'oci network vcn list': `{ \"data\": [{\"display-name\": \"prod-vcn\", \"cidr-block\": \"10.0.0.0/16\"}] }`,\n    'oci iam compartment list': `{ \"data\": [{\"name\": \"Production\"}, {\"name\": \"Dev\"}] }`\n  };\n  function esc(s){ return s.replace(/[&<>]/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c])); }\n  function print(cmd, text, isErr){\n    const line = document.createElement('div');\n    line.innerHTML = `<div class=\"cmdline\">${esc(cmd)}</div><div style=\"color:${isErr?'#ff8a7a':'#c9f7d8'}; margin:4px 0 12px; white-space:pre-wrap;\">${esc(text)}</div>`;\n    out.appendChild(line); out.scrollTop = out.scrollHeight;\n  }\n  print('help', 'Combined Linux + OCI CLI simulator. Type \"help\" for commands.');\n  input.addEventListener('keydown', e=>{\n    if(e.key!=='Enter') return;\n    const cmd = input.value.trim(); input.value=''; if(!cmd) return;\n    if(cmd==='clear'){ out.innerHTML=''; return; }\n    if(responses[cmd]){ print(cmd, responses[cmd]); return; }\n    print(cmd, 'Command not recognized in this simulator. Type \"help\" for the supported list.', true);\n  });\n}\n\n/* ---------- troubleshooting lab 3 ---------- */\nfunction initTroubleshootLab3(){\n  const btns = document.querySelectorAll('#ts3-case-btns .chip-btn'); if(!btns.length) return;\n  const panel = document.getElementById('ts3-panel');\n  const cases = {\n    dns: {err:'curl: (6) Could not resolve host: api.internal.example.com', hint:'Check whether the VCN\\'s DNS resolution is enabled and the correct DNS label/zone is configured.', fix:'Fix: enable DNS hostnames in the VCN settings, or verify the private DNS zone has the correct A record for the internal service.'},\n    routing: {err:'Instance in subnet A cannot reach a host in subnet B of the same VCN.', hint:'Check the route table attached to subnet A.', fix:'Fix: add a route rule in subnet A\\'s route table pointing to the correct target (local VCN routing is automatic for VCN-internal traffic; check for an overriding rule or a missing route to a DRG/peering).'},\n    subnet: {err:'Error: CIDR block 10.0.1.0/24 overlaps with an existing subnet.', hint:'Subnets within the same VCN cannot have overlapping CIDR ranges.', fix:'Fix: choose a non-overlapping CIDR block, e.g. 10.0.2.0/24, that fits within the VCN\\'s overall CIDR and doesn\\'t collide with existing subnets.'},\n    firewall: {err:'Connection timed out connecting to db-host:5432.', hint:'Check both the Security List/NSG and the OS-level firewall (firewalld/iptables).', fix:'Fix: add an ingress rule allowing TCP/5432 from the app subnet\\'s CIDR in the Security List or NSG, and confirm firewalld isn\\'t blocking it on the host itself.'},\n    tls: {err:'SSL: certificate verify failed: unable to get local issuer certificate', hint:'The client doesn\\'t trust the certificate chain presented by the server.', fix:'Fix: install the correct intermediate/root CA certificate on the client, or fix the server to send the full certificate chain, not just the leaf cert.'},\n    api: {err:'HTTP/1.1 401 Unauthorized \u2014 {\"code\":\"NotAuthenticated\"}', hint:'A 401 means the request signing/authentication itself failed, before authorization is even checked.', fix:'Fix: verify the request signature was built correctly (date header, signing string, key), and that the API key hasn\\'t been deactivated.'}\n  };\n  function render(key){\n    const c = cases[key];\n    panel.innerHTML = `<p class=\"mono\" style=\"color:var(--red-bright);\">${c.err}</p>\n      <button class=\"chip-btn active mt-lg\" id=\"ts3-hint-btn\">\ud83d\udca1 Show hint</button>\n      <p class=\"small mt-lg\" id=\"ts3-hint\" style=\"display:none;\">${c.hint}</p>\n      <button class=\"chip-btn mt-lg\" id=\"ts3-fix-btn\" style=\"display:none;\">\u2713 Reveal fix</button>\n      <p class=\"small mt-lg\" id=\"ts3-fix\" style=\"display:none; color:var(--green);\">${c.fix}</p>`;\n    document.getElementById('ts3-hint-btn').addEventListener('click', function(){ document.getElementById('ts3-hint').style.display='block'; document.getElementById('ts3-fix-btn').style.display='inline-flex'; this.disabled=true; });\n    document.getElementById('ts3-fix-btn').addEventListener('click', function(){ document.getElementById('ts3-fix').style.display='block'; this.disabled=true; });\n  }\n  btns.forEach(b=> b.addEventListener('click', ()=>{ btns.forEach(x=>x.classList.remove('active')); b.classList.add('active'); render(b.dataset.case3); }));\n  render('dns');\n}\n\n;\n\n/* ---------- flashcards 3 ---------- */\nfunction initFlashcards3(){\n  const wrap = document.getElementById('flash-wrap3'); if(!wrap) return;\n  const cards = [\n    ['Kernel','Core program managing scheduling, memory, filesystems, drivers'],\n    ['chmod 755','rwxr-xr-x \u2014 owner full, group/others read+execute'],\n    ['Zombie process','Finished but not yet reaped by its parent'],\n    ['systemd unit','A managed service definition (start/stop/enable/disable)'],\n    ['CIDR /24','256 addresses total, 254 usable hosts'],\n    ['ARP','Resolves an IP address to a MAC address on the local segment'],\n    ['DNS resolution order','Cache \u2192 Root \u2192 TLD \u2192 Authoritative'],\n    ['NAT','Translates private IPs to a shared public IP for outbound traffic'],\n    ['TLS handshake','Negotiates keys and verifies identity before encrypted data flows'],\n    ['Stateful firewall','Automatically allows return traffic for an established connection'],\n    ['Instance Principal','Lets a compute instance authenticate as itself, no embedded key'],\n    ['429 status code','Too Many Requests \u2014 rate limited, back off and retry'],\n  ];\n  wrap.innerHTML = cards.map(([f,b])=>`<div class=\"flashcard\"><div class=\"fc-inner\"><div class=\"fc-face fc-front\">${f}</div><div class=\"fc-face fc-back\">${b}</div></div></div>`).join('');\n  wrap.querySelectorAll('.flashcard').forEach(fc=> fc.addEventListener('click', ()=> fc.classList.toggle('flipped')));\n}\n\n/* ---------- certification quiz 3 ---------- */\nfunction initQuiz3(){\n  const wrap = document.getElementById('quiz-wrap3'); if(!wrap) return;\n  const Q = [\n    {q:'Which component of Linux directly manages CPU scheduling and memory allocation?', o:['Shell','Kernel','GNU utilities','Package manager'], c:1, e:'The kernel is the core program that manages hardware resources including scheduling and memory.'},\n    {q:'What does chmod 644 grant?', o:['Owner rwx, group rwx, others rwx','Owner rw-, group r--, others r--','Owner r--, group rw-, others rw-','No permissions to anyone'], c:1, e:'6=rw-, 4=r--, 4=r-- \u2192 owner read/write, group and others read-only.'},\n    {q:'A process that has finished executing but hasn\\'t been reaped by its parent is called a:', o:['Daemon','Orphan','Zombie','Thread'], c:2, e:'A zombie process still holds a process table entry until its parent collects its exit status.'},\n    {q:'Which command manages systemd services (start, stop, enable)?', o:['service', 'systemctl', 'initctl', 'chkconfig'], c:1, e:'systemctl is the standard tool for managing systemd units on modern distributions.'},\n    {q:'On Oracle Linux/RHEL, which package manager is standard today?', o:['apt','dnf','pip','npm'], c:1, e:'dnf (successor to yum) is standard on modern RHEL-family distributions including Oracle Linux.'},\n    {q:'A /26 subnet provides how many usable host addresses?', o:['254','126','62','30'], c:2, e:'/26 = 2^6 = 64 total addresses, minus network and broadcast = 62 usable.'},\n    {q:'Which protocol resolves an IP address to a MAC address on a local network segment?', o:['DNS','DHCP','ARP','NAT'], c:2, e:'ARP (Address Resolution Protocol) maps IP addresses to MAC addresses on the local segment.'},\n    {q:'In DNS resolution, which server is queried right after the Root server for \"example.com\"?', o:['Authoritative server for example.com','TLD server for .com','Local DNS cache','ISP router'], c:1, e:'The Root server refers the resolver to the TLD server (.com), which then refers to the authoritative server.'},\n    {q:'Which of the following is TRUE about TCP vs UDP?', o:['UDP guarantees delivery order','TCP has lower latency than UDP','TCP retransmits lost segments; UDP does not','UDP is connection-oriented'], c:2, e:'TCP is connection-oriented and reliable (with retransmission); UDP is connectionless and best-effort.'},\n    {q:'A stateless firewall, unlike a stateful one, requires:', o:['No rules at all','An explicit rule for return traffic in each direction','MFA for every packet','A VPN tunnel'], c:1, e:'Stateless firewalls evaluate each packet independently, so return traffic needs its own explicit rule.'},\n    {q:'Which OCI authentication method is most appropriate for code running ON an OCI compute instance, with no embedded credentials?', o:['API key in config file','Session token','Instance principal','Username/password'], c:2, e:'Instance principals let a compute instance authenticate as itself without any embedded long-lived key.'},\n    {q:'A CLI command returns \"NotAuthorizedOrNotFound.\" The most likely first thing to check is:', o:['Network connectivity','Whether the IAM policy grants sufficient permission on this resource','The region name spelling','The OS package version'], c:1, e:'This error deliberately conflates \"doesn\\'t exist\" with \"not authorized\" \u2014 check the policy first.'},\n    {q:'Which HTTP status code indicates the request succeeded and created a new resource?', o:['200','201','204','409'], c:1, e:'201 Created specifically indicates successful resource creation.'},\n    {q:'A 429 response from the OCI API means you should:', o:['Retry immediately in a tight loop','Back off and retry after a delay','Regenerate your API key','Switch regions'], c:1, e:'429 Too Many Requests indicates rate limiting \u2014 the correct response is backoff and retry, not hammering the API again.'},\n    {q:'The Console, CLI, SDKs, and REST API in OCI are best described as:', o:['Four unrelated systems','Different wrappers around the same underlying REST API','Only the CLI talks to the real API','SDKs bypass authentication entirely'], c:1, e:'All four are different clients built on top of the same signed REST API calls.'},\n    {q:'Where does the OCI CLI look for connection/auth details by default?', o:['/etc/oci.conf','~/.oci/config','Environment variable OCI_KEY only','A database'], c:1, e:'~/.oci/config is the default CLI configuration file location, containing user, tenancy, fingerprint, key_file, and region.'},\n    {q:'Which of these is a private (RFC 1918) IPv4 range?', o:['8.8.8.0/24','172.16.0.0/12','203.0.113.0/24','198.51.100.0/24'], c:1, e:'172.16.0.0/12 is one of the three RFC 1918 private ranges, along with 10.0.0.0/8 and 192.168.0.0/16.'},\n    {q:'In the OSI model, at which layer do switches primarily operate?', o:['Layer 1 (Physical)','Layer 2 (Data Link)','Layer 3 (Network)','Layer 4 (Transport)'], c:1, e:'Switches forward frames using MAC addresses, which is Layer 2 (Data Link) functionality.'},\n    {q:'What is the primary security risk of running \"chmod 777\" on a script?', o:['It makes the file unreadable','Any local user or compromised process can modify/replace the script','It deletes the file automatically','It disables logging'], c:1, e:'777 makes the file world-writable, letting any local account or code execution overwrite it with malicious content.'},\n  ];\n  state.quizTotal = Q.length;\n  wrap.innerHTML = Q.map((item,qi)=>`\n    <div class=\"quiz-q\" id=\"quiz3-${qi}\">\n      <div class=\"qtext\">${qi+1}. ${item.q}</div>\n      <div class=\"quiz-opts\">${item.o.map((opt,oi)=>`<label class=\"quiz-opt\"><input type=\"radio\" name=\"q3-${qi}\" value=\"${oi}\"> ${opt}</label>`).join('')}</div>\n      <div class=\"quiz-explain\">${item.e}</div>\n    </div>`).join('');\n  wrap.querySelectorAll('.quiz-q').forEach((qEl, qi)=>{\n    qEl.addEventListener('change', e=>{\n      if(qEl.classList.contains('answered')) return;\n      qEl.classList.add('answered');\n      const chosen = parseInt(e.target.value);\n      qEl.querySelectorAll('.quiz-opt').forEach((o,oi)=>{ if(oi===Q[qi].c) o.classList.add('correct'); else if(oi===chosen) o.classList.add('incorrect'); });\n      state.quizAnswered++; if(chosen===Q[qi].c) state.quizScore++;\n      document.getElementById('score-chip-val').textContent = `${state.quizScore} / ${state.quizAnswered}`;\n      document.getElementById('quiz-final-score3').textContent = `${state.quizScore} / ${Q.length}`;\n      document.getElementById('cert-score-display3').textContent = `${state.quizScore}/${Q.length}`;\n      updateBadge3();\n    });\n  });\n}\n\n/* ---------- badge / certificate 3 ---------- */\nfunction updateBadge3(){\n  const scrollPct = window.__lastScrollPct3 || 0;\n  const quizPct = state.quizTotal ? (state.quizAnswered/state.quizTotal)*100 : 0;\n  const combined = Math.round(scrollPct*0.5 + quizPct*0.5);\n  const circle = document.getElementById('badge-circle3'); if(!circle) return;\n  circle.style.setProperty('--pct', (combined*3.6)+'deg');\n  document.getElementById('badge-pct3').textContent = combined+'%';\n  const title = document.getElementById('badge-title3'); const sub = document.getElementById('badge-sub3');\n  if(combined>=95){ title.textContent='\ud83c\udfc6 Day 3 Complete'; sub.textContent='Certificate preview unlocked below.'; }\n  else if(combined>=50){ title.textContent='\ud83d\udfe0 Halfway there'; sub.textContent='Keep going through the remaining sections and the quiz.'; }\n  else { title.textContent='Keep going'; sub.textContent='Complete every section and the quiz to preview your certificate.'; }\n  const d = new Date(); document.getElementById('cert-date-display3').textContent = d.toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'});\n}\n"};
